function updatePanel(){
 const own=selectedOwner();
 const gameCell=(selected&&selected.key===MAX_GAME_LEVEL3233)?selected.i:-1;
 const ownCell=gameCell>=0&&playerCountry>=0&&owner6[gameCell]===playerCountry;
 const coast=gameCell>=0&&isCoastal3212(gameCell);

 startBtn.disabled=!(selected&&own>=0&&playerCountry<0);
 startBtn.style.display=playerCountry<0?'block':'none';
 attackBtn.disabled=!(gameCell>=0&&isFrontTarget(gameCell)&&gold3212>=8);
 capitalBtn.disabled=!(ownCell&&capitals[playerCountry]!==gameCell);
 fortBtn.disabled=!(ownCell&&gold3212>=35);
 cityBtn.disabled=!(ownCell&&!cities3212.has(gameCell)&&gold3212>=60);
 industryBtn.disabled=!(ownCell&&!industries3212.has(gameCell)&&gold3212>=80);
 portBtn.disabled=!(ownCell&&coast&&!ports3212.has(gameCell)&&gold3212>=45);
 roadBtn.disabled=!(ownCell&&gold3212>=10);
 fleetBtn.disabled=!(ownCell&&ports3212.has(gameCell)&&gold3212>=35);
 cancelBtn.disabled=!targetMode3212;

 modeLine3212.classList.toggle('show',!!targetMode3212);
 if(targetMode3212==='road')modeLine3212.textContent='CARRETERA: selecciona otro territorio propio · ✕ para cancelar';
 else if(targetMode3212==='fleet')modeLine3212.textContent='FLOTA: selecciona una costa de destino · ✕ para cancelar';
 else modeLine3212.textContent='';

 if(!selected){
  selEl.textContent=playerCountry>=0?COUNTRY_NAMES[playerCountry]:'Globo experimental';
  selSub.textContent=playerCountry>=0?'Selecciona territorio. Acércate para operar, construir infraestructura o lanzar una flota.':'Selecciona una zona de tierra para comenzar.';
  return;
 }
 const L=loadLevel(selected.key),ix=selected.i*3;
 const v=[L.centers[ix]/32767,L.centers[ix+1]/32767,L.centers[ix+2]/32767];
 const lat=Math.asin(Math.max(-1,Math.min(1,v[1])))*180/Math.PI;
 const lon=Math.atan2(v[0],v[2])*180/Math.PI;
 const geom=(L.offsets[selected.i+1]-L.offsets[selected.i])===5?'Pentágono':'Hexágono';
 if(own<0){
  selEl.textContent=`${geom} oceánico`;
  selSub.textContent=`${Math.abs(lat).toFixed(1)}°${lat>=0?'N':'S'} · ${Math.abs(lon).toFixed(1)}°${lon>=0?'E':'O'}`;
 }else{
  selEl.textContent=COUNTRY_NAMES[own]||'Territorio';
  let tags=[];
  if(gameCell>=0){
   if(isCoastal3212(gameCell))tags.push('costa');
   const mt=mountainTier3212[gameCell]||0;if(mt)tags.push(mt>=3?'alta montaña':'montaña');
   if(forts3212[gameCell])tags.push(`defensa ${forts3212[gameCell]}`);
   if(cities3212.has(gameCell))tags.push('ciudad');
   if(industries3212.has(gameCell))tags.push('industria');
   if(ports3212.has(gameCell))tags.push('puerto');
   if(playerCountry>=0&&capitals[playerCountry]===gameCell)tags.push('capital');
  }
  let msg=`${geom} · ${Math.abs(lat).toFixed(1)}°${lat>=0?'N':'S'} · ${Math.abs(lon).toFixed(1)}°${lon>=0?'E':'O'}`;
  if(playerCountry>=0){
   if(own===playerCountry)msg+=' · territorio propio';
   else if(selected.key!==MAX_GAME_LEVEL3233)msg+=' · acércate más para operar';
   else if(isFrontTarget(selected.i))msg+=' · frontera atacable';
   else msg+=' · fuera de tu frente';
  }
  if(tags.length)msg+=' · '+tags.join(' · ');
  selSub.textContent=msg;
 }
}
function relocateCapital(country,oldCell){
 if(country<0)return;
 let best=-1,bestDot=-2;
 const L6=loadLevel(MAX_GAME_LEVEL3233),ix=oldCell*3;
 const ox=L6.centers[ix]/32767,oy=L6.centers[ix+1]/32767,oz=L6.centers[ix+2]/32767;
 for(let i=0;i<owner6.length;i++){
  if(owner6[i]!==country)continue;
  const j=i*3,x=L6.centers[j]/32767,y=L6.centers[j+1]/32767,z=L6.centers[j+2]/32767;
  const d=x*ox+y*oy+z*oz;
  if(d>bestDot){bestDot=d;best=i}
 }
 capitals[country]=best;
}
function countPlayerCells(){
 if(playerCountry<0)return 0;
 let n=0;for(let i=0;i<owner6.length;i++)if(owner6[i]===playerCountry)n++;
 return n;
}


function edgeKey3212(a,b){return a<b?a+','+b:b+','+a}
function isCoastal3212(i){
 const L=loadLevel(MAX_GAME_LEVEL3233),s=L.offsets[i],e=L.offsets[i+1];
 for(let k=s;k<e;k++){const n=L.edgeNbr[k];if(n>=0&&L.land[n]<0)return true}
 return false;
}
function rebuildRoadEdges3212(){
 roadEdgeSet3212.clear();
 for(const path of roads3212)for(let i=1;i<path.length;i++)roadEdgeSet3212.add(edgeKey3212(path[i-1],path[i]));
}
function initTerrainGameplay3212(){
 const L=loadLevel(MAX_GAME_LEVEL3233);
 mountainTier3212=new Uint8Array(L.n);forts3212=new Uint8Array(L.n);
 for(let i=0;i<MOUNTAIN_CELL_PAIRS3212.length;i+=2)mountainTier3212[MOUNTAIN_CELL_PAIRS3212[i]]=MOUNTAIN_CELL_PAIRS3212[i+1];
 riverEdgeSet3212.clear();
 for(let i=0;i<RIVER_EDGE_PAIRS3212.length;i+=2)riverEdgeSet3212.add(edgeKey3212(RIVER_EDGE_PAIRS3212[i],RIVER_EDGE_PAIRS3212[i+1]));
}
function saveGame3212(){
 try{
  const s={playerCountry,gold:gold3212,owner:Array.from(owner6),capitals,
   cities:[...cities3212],industries:[...industries3212],ports:[...ports3212],forts:Array.from(forts3212),roads:roads3212};
  localStorage.setItem(SAVE_KEY3212,JSON.stringify(s));
 }catch(e){}
}
function loadGame3212(){
 try{
  const raw=localStorage.getItem(SAVE_KEY3212);if(!raw)return false;
  const s=JSON.parse(raw);if(!s||!Array.isArray(s.owner)||s.owner.length!==owner6.length)return false;
  owner6.set(s.owner);playerCountry=Number.isInteger(s.playerCountry)?s.playerCountry:-1;gold3212=Number(s.gold)||180;
  if(Array.isArray(s.capitals))capitals=s.capitals.slice();
  cities3212=new Set(s.cities||[]);industries3212=new Set(s.industries||[]);ports3212=new Set(s.ports||[]);
  if(Array.isArray(s.forts)&&s.forts.length===forts3212.length)forts3212.set(s.forts);
  roads3212=Array.isArray(s.roads)?s.roads:[];rebuildRoadEdges3212();cacheDirty=true;return true;
 }catch(e){return false}
}
function income3212(){
 if(playerCountry<0)return 0;
 const owned=countPlayerCells();
 return 2.5+owned*.012+cities3212.size*.75+industries3212.size*1.55+ports3212.size*.45;
}
function findOwnedPath3212(start,goal){
 if(start===goal)return [start];
 const L=loadLevel(MAX_GAME_LEVEL3233),prev=new Int32Array(L.n);prev.fill(-2);prev[start]=-1;
 const q=new Int32Array(L.n);let h=0,t=0;q[t++]=start;
 while(h<t){
  const u=q[h++],s=L.offsets[u],e=L.offsets[u+1];
  for(let k=s;k<e;k++){
   const n=L.edgeNbr[k];if(n<0||prev[n]!==-2||owner6[n]!==playerCountry)continue;
   prev[n]=u;if(n===goal){h=t;break}q[t++]=n;
  }
 }
 if(prev[goal]===-2)return null;
 const path=[];let u=goal;while(u>=0){path.push(u);u=prev[u]}return path.reverse();
}
function cancelMode3212(){targetMode3212=null;targetSource3212=-1;updatePanel();needsRender=true}
function startRoad3212(){
 if(!selected||selected.key!==MAX_GAME_LEVEL3233||owner6[selected.i]!==playerCountry)return;
 targetMode3212='road';targetSource3212=selected.i;updatePanel();needsRender=true;
}
function finishRoad3212(dest){
 if(targetSource3212<0||owner6[dest]!==playerCountry){toast('El destino debe ser territorio propio');return}
 const p=findOwnedPath3212(targetSource3212,dest);if(!p||p.length<2){toast('No hay ruta terrestre propia');cancelMode3212();return}
 const cost=Math.max(10,Math.round((p.length-1)*1.7));if(gold3212<cost){toast(`Necesitas ${cost} de oro`);return}
 gold3212-=cost;roads3212.push(p);rebuildRoadEdges3212();toast(`Carretera construida · ${cost} oro`);cancelMode3212();saveGame3212();
}
function startFleet3212(){
 if(!selected||selected.key!==MAX_GAME_LEVEL3233||!ports3212.has(selected.i))return;
 targetMode3212='fleet';targetSource3212=selected.i;updatePanel();needsRender=true;
}
function finishFleet3212(dest){
 if(!isCoastal3212(dest)||loadLevel(MAX_GAME_LEVEL3233).land[dest]<0){toast('La flota necesita una costa de destino');return}
 if(gold3212<35){toast('Necesitas 35 de oro');return}
 const L=loadLevel(MAX_GAME_LEVEL3233),a=targetSource3212*3,b=dest*3;
 const av=[L.centers[a]/32767,L.centers[a+1]/32767,L.centers[a+2]/32767],bv=[L.centers[b]/32767,L.centers[b+1]/32767,L.centers[b+2]/32767];
 const angle=Math.acos(Math.max(-1,Math.min(1,av[0]*bv[0]+av[1]*bv[1]+av[2]*bv[2])));
 gold3212-=35;fleets3212.push({from:targetSource3212,to:dest,start:performance.now(),duration:2600+angle*4800});
 toast('Flota en ruta');cancelMode3212();saveGame3212();needsRender=true;
}
function slerp3212(a,b,t){
 const d=Math.max(-1,Math.min(1,a[0]*b[0]+a[1]*b[1]+a[2]*b[2])),th=Math.acos(d);
 if(th<1e-5)return a.slice();const s=Math.sin(th),u=Math.sin((1-t)*th)/s,v=Math.sin(t*th)/s;
 const r=[a[0]*u+b[0]*v,a[1]*u+b[1]*v,a[2]*u+b[2]*v],n=Math.hypot(...r);return r.map(x=>x/n);
}
function updateFleets3212(now){
 if(!fleets3212.length)return;
 const remain=[];
 for(const f of fleets3212){
  const t=(now-f.start)/f.duration;
  if(t<1){remain.push(f);continue}
  const old=owner6[f.to];
  if(old>=0&&old!==playerCountry){
   if(forts3212[f.to]>=2){forts3212[f.to]--;toast('El desembarco fue rechazado por las defensas')}
   else{owner6[f.to]=playerCountry;forts3212[f.to]=0;if(capitals[old]===f.to)relocateCapital(old,f.to);cacheDirty=true;toast('Desembarco completado')}
  }
 }
 fleets3212=remain;if(cacheDirty)saveGame3212();
}
function drawTerrain3212(R,cx,cy){
 if(zoom<.95)return;const L=loadLevel(MAX_GAME_LEVEL3233),F=L.faceCenters;
 function drawSystems(list,mountain){
  for(const sys of list){
   ctx.beginPath();let any=false;const e=sys.e;
   for(let j=0;j<e.length;j+=2){
    const a=e[j]*3,b=e[j+1]*3;
    const p=projectVec(F[a]/32767,F[a+1]/32767,F[a+2]/32767,R,cx,cy),q=projectVec(F[b]/32767,F[b+1]/32767,F[b+2]/32767,R,cx,cy);
    if(p[2]<.015||q[2]<.015)continue;ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);any=true;
   }
   if(!any)continue;
   if(mountain){ctx.strokeStyle=sys.t>=3?'rgba(225,205,170,.54)':'rgba(199,180,153,.42)';ctx.lineWidth=(sys.t>=3?1.7:1.15)*Math.min(1.7,Math.sqrt(zoom));}
   else{ctx.strokeStyle=sys.t>=3?'rgba(91,190,228,.80)':'rgba(91,190,228,.60)';ctx.lineWidth=(sys.t>=3?1.3:.9)*Math.min(1.6,Math.sqrt(zoom));}
   ctx.stroke();
  }
 }
 drawSystems(MOUNTAIN_SYSTEMS3212,true);drawSystems(RIVER_SYSTEMS3212,false);
}
function drawInfrastructure3212(R,cx,cy,now){
 const L=loadLevel(MAX_GAME_LEVEL3233),C=L.centers;
 // Roads
 ctx.lineCap='round';
 for(const path of roads3212){
  ctx.beginPath();let started=false;
  for(let j=0;j<path.length;j++){
   const i=path[j]*3,p=projectVec(C[i]/32767,C[i+1]/32767,C[i+2]/32767,R,cx,cy);
   if(p[2]<.02){started=false;continue}if(!started){ctx.moveTo(p[0],p[1]);started=true}else ctx.lineTo(p[0],p[1]);
  }
  ctx.strokeStyle='rgba(239,207,108,.70)';ctx.lineWidth=Math.max(.8,1.15*Math.sqrt(zoom));ctx.stroke();
 }
 // v3.24.9: recovered vector map icons from the v3.20.1 branch.
 // They remain screen-sized on the globe, so zoom does not turn them into blobs.
 if(zoom>1.85){
  const px=globeIconScale3249();
  // Draw less important infrastructure first so the most important symbol stays legible.
  if(zoom>2.15){
   for(const id of industries3212){
    if(owner6[id]<0)continue;const j=id*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
    if(globeIconVisible3249(p))drawGlobeIndustryIcon3249(p[0],p[1],id,px*.82);
   }
   for(const id of ports3212){
    if(owner6[id]<0)continue;const j=id*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
    if(globeIconVisible3249(p))drawGlobePortIcon3249(p[0],p[1],id,px*.86);
   }
   for(const id of cities3212){
    if(owner6[id]<0)continue;const j=id*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
    if(globeIconVisible3249(p))drawGlobeCityIcon3249(p[0],p[1],id,px*.88);
   }
  }
 }
 // Fleets v3.26.1: only their validated SEA route is drawn.
 drawFleetsSea3261(R,cx,cy,now,C);
}
function operation3212(target){
 if(!isFrontTarget(target)||gold3212<8)return;
 const old=owner6[target],strength=Number(strength3212.value),advance=Number(advance3212.value);
 let power=2+Math.floor(strength/25)+Math.floor(advance/25),maxCells=1+Math.floor(advance/20)+Math.floor(strength/50);
 const q=[target],seen=new Set([target]),captured=[];let head=0;
 const L=loadLevel(MAX_GAME_LEVEL3233);
 while(head<q.length&&captured.length<maxCells&&power>0){
  const u=q[head++];if(owner6[u]!==old)continue;
  let friendly=-1;const s=L.offsets[u],e=L.offsets[u+1];for(let k=s;k<e;k++){const n=L.edgeNbr[k];if(n>=0&&owner6[n]===playerCountry){friendly=n;break}}
  if(friendly<0)continue;
  let cost=1+(mountainTier3212[u]>=3?2:mountainTier3212[u]?1:0)+(forts3212[u]||0)*2;
  const ek=edgeKey3212(u,friendly);if(riverEdgeSet3212.has(ek))cost++;if(roadEdgeSet3212.has(ek))cost=Math.max(1,cost-1);
  if(cost>power)continue;power-=cost;owner6[u]=playerCountry;forts3212[u]=0;captured.push(u);
  if(capitals[old]===u)relocateCapital(old,u);
  for(let k=s;k<e;k++){const n=L.edgeNbr[k];if(n>=0&&owner6[n]===old&&!seen.has(n)){seen.add(n);q.push(n)}}
 }
 if(captured.length){gold3212-=Math.min(gold3212,8+captured.length*2);cacheDirty=true;toast(`Operación: ${captured.length} territorio${captured.length===1?'':'s'} conquistado${captured.length===1?'':'s'}`);saveGame3212()}
 else toast('La defensa y el terreno han detenido la operación');
 updatePanel();needsRender=true;
}
function build3212(type){
 if(!selected||selected.key!==MAX_GAME_LEVEL3233||owner6[selected.i]!==playerCountry)return;const i=selected.i;
 if(type==='fort'){const cost=35;if(gold3212<cost)return;gold3212-=cost;forts3212[i]=Math.min(3,forts3212[i]+1);toast('Defensas reforzadas')}
 if(type==='city'){if(gold3212<60||cities3212.has(i))return;gold3212-=60;cities3212.add(i);toast('Ciudad desarrollada')}
 if(type==='industry'){if(gold3212<80||industries3212.has(i))return;gold3212-=80;industries3212.add(i);toast('Industria construida')}
 if(type==='port'){if(gold3212<45||ports3212.has(i)||!isCoastal3212(i))return;gold3212-=45;ports3212.add(i);toast('Puerto construido')}
 saveGame3212();updatePanel();needsRender=true;
}
function aiTick3212(){
 if(playerCountry<0||gameSpeed3212<=0)return;const L=loadLevel(MAX_GAME_LEVEL3233);let changed=false;
 const attempts=Math.max(1,gameSpeed3212);
 for(let a=0;a<attempts;a++){
  for(let tries=0;tries<80;tries++){
   const u=(Math.random()*L.n)|0,att=owner6[u];if(att<0||att===playerCountry&&Math.random()<.55)continue;
   const s=L.offsets[u],e=L.offsets[u+1],opts=[];for(let k=s;k<e;k++){const n=L.edgeNbr[k];if(n>=0&&owner6[n]>=0&&owner6[n]!==att)opts.push(n)}
   if(!opts.length)continue;const v=opts[(Math.random()*opts.length)|0],def=owner6[v];
   const chance=.46-(forts3212[v]||0)*.11-(mountainTier3212[v]>=3?.10:0);if(Math.random()>chance)break;
   owner6[v]=att;forts3212[v]=0;if(capitals[def]===v)relocateCapital(def,v);changed=true;break;
  }
 }
 if(changed){cacheDirty=true;needsRender=true;saveGame3212()}
}
function economyTick3212(){
 if(playerCountry<0||gameSpeed3212<=0)return;lastIncome3212=income3212()*gameSpeed3212;gold3212+=lastIncome3212;updatePanel();needsRender=true;saveGame3212();
}


function renderIds3233(key,R,cx,cy){
 if(key!==MAX_GAME_LEVEL3233)return null;const P=loadLevel('5'),g=loadGroups('5'),C=P.centers,ids=[],margin=Math.max(120,Math.min(360,R*.055));
 for(let p=0;p<P.n;p++){const j=p*3,pr=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);if(pr[2]<-.06||pr[0]<-margin||pr[0]>vw+margin||pr[1]<-margin||pr[1]>vh+margin)continue;for(let k=g.offsets[p];k<g.offsets[p+1];k++)ids.push(g.ids[k])}return ids;
}


