  if(!l.id||ids.has(l.id))errors.push(`ID duplicado: ${l.id||'(vacío)'}`);else ids.add(l.id);const nm=normalizeLabelName3243(l.name);
  if(!l.name||names.has(nm))errors.push(`Nombre duplicado: ${l.name||'(vacío)'}`);else names.add(nm);
  if(!Number.isFinite(l.lat)||!Number.isFinite(l.lon)||l.lat<-90||l.lat>90||l.lon<-180||l.lon>180)errors.push(`Coordenadas inválidas: ${l.id}`);
