function relationName3220(v){return v===-1?'GUERRA':v===1?'COMERCIO':v===2?'NO AGRESIÓN':v===3?'ALIANZA':'NEUTRAL'}
function relationColor3220(v){return v===-1?'#e86f70':v===1?'#72d9c6':v===2?'#d4c778':v===3?'#78b7ff':'#788b9e'}
function tradePartners3220(){let n=0;for(let i=0;i<relations3220.length;i++)if(relations3220[i]===1||relations3220[i]===3)n++;return n}
function tradeIncome3220(){if(playerCountry<0)return 0;const p=tradePartners3220();return p*(1.1+ports3212.size*.08)+research3220.industry*.35}
const _income3212_3220=income3212;
