function findPathToTarget3230(target,targetOwner){
 const L=loadLevel(MAX_GAME_LEVEL3233);if(target<0||L.land[target]<0)return null;
 const prev=new Int32Array(L.n);prev.fill(-2);const q=new Int32Array(L.n);let h=0,t=0;q[t++]=target;prev[target]=-1;let source=-1;
 while(h<t&&t<L.n){
  const u=q[h++],s=L.offsets[u],e=L.offsets[u+1];
  for(let k=s;k<e;k++){
   const n=L.edgeNbr[k];if(n<0||L.land[n]<0||prev[n]!==-2)continue;
   if(owner6[n]===0){prev[n]=u;source=n;h=t;break}
   const o=owner6[n];
   const allow=targetOwner<0?(o<0):(o<0||o===targetOwner);
   if(!allow)continue;prev[n]=u;q[t++]=n;
  }
 }
 if(source<0)return null;
 const path=[source];let u=prev[source];let guard=0;
 while(u>=0&&guard++<L.n){path.push(u);if(u===target)break;u=prev[u]}
 return path[path.length-1]===target?path:null;
}
