 if(targetSource3212<0||!isCoastal3212(dest)||loadLevel(MAX_GAME_LEVEL3233).land[dest]<0){toast('El destino necesita costa');return}
 if(owner6[dest]===0){toast('La costa ya es tuya');return}
 const amount=Math.floor(troops3230[0]*Number(strength3212.value)/100);if(amount<15||gold3212<55){toast('Necesitas 55 oro y al menos 15 tropas');return}
 const L=loadLevel(MAX_GAME_LEVEL3233),a=targetSource3212*3,b=dest*3,av=[L.centers[a]/32767,L.centers[a+1]/32767,L.centers[a+2]/32767],bv=[L.centers[b]/32767,L.centers[b+1]/32767,L.centers[b+2]/32767];
 const angle=Math.acos(Math.max(-1,Math.min(1,av[0]*bv[0]+av[1]*bv[1]+av[2]*bv[2]))),travel=Math.max(9000,Math.min(165000,8000+angle*43000*(1-research3230.levels.technology*.035)));
