 const i=selectedGameCell3230(),panel=document.getElementById('panel');panel.classList.toggle('open',i>=0||!!targetMode3212);
 document.getElementById('territoryStat').textContent=started3230?countFaction3230(0).toLocaleString('es-ES'):'0';
