 if(roads3212.some(p=>p.includes(i)))extras.push('🛣 carretera');if(mountainTier3212[i])extras.push(mountainTier3212[i]>=3?'alta montaña':'montaña');if(isCoastal3212(i))extras.push('costa');
 document.getElementById('sel').textContent=(neutral?'Terreno libre':factionName3230(o))+' · '+geo;
