terrainStrategicFill3247=function(key,i,L,own,z){
 if(L.land[i]<0)return shadeColor('#17384f',z);
 const type=terrainType3247(key,i,L);
 const base=TERRAIN_PALETTE3247[type]||TERRAIN_PALETTE3247.plain;

 if(mapMode3252==='terrain'){
   return shadedRGB3247(base,z);
 }

 // Supply only changes the base at gameplay LOD; the existing logistics
 // overlay paints only visible player cells and does not allocate a world texture.
 if(mapMode3252==='supply'){
   if(key!==MAX_GAME_LEVEL3233||zoom<2){
     if(own<0)return shadedRGB3247(base,z);
     const rgb=FACTION_RGB3252[own]||[90,110,125];
     return shadedRGB3247(mixRGB3247(base,rgb,.30),z);
   }
   if(own===0)return shadedRGB3247(mixRGB3247(base,[55,72,70],.26),z);
   return shadedRGB3247(mixRGB3247(base,[26,34,42],.56),z);
 }

 // Political = the mixed physical/political look already used in v3.25.1.
 if(own<0)return shadedRGB3247(base,z);
 const factionRGB=FACTION_RGB3252[own]||[90,110,125];
 const tint=zoom<1.7?.58:zoom<3.5?.50:zoom<7?.43:.36;
 return shadedRGB3247(mixRGB3247(base,factionRGB,tint),z);
};

// ---------- Rhine: complete Alpine / Upper / Middle / Lower Rhine ----------
// The old river started around Cologne.  These are 25 REAL shared gameplay
