function drawFaceNodeEdge3252(u,v,R,cx,cy,outerW,outerC,innerW,innerC){
 const L=loadLevel(MAX_GAME_LEVEL3233),F=L.faceCenters,a=u*3,b=v*3;
 const p=projectVec(F[a]/32767,F[a+1]/32767,F[a+2]/32767,R,cx,cy),
       q=projectVec(F[b]/32767,F[b+1]/32767,F[b+2]/32767,R,cx,cy);
 if(p[2]<.015||q[2]<.015)return false;
 ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);
 ctx.strokeStyle=outerC;ctx.lineWidth=outerW;ctx.stroke();
 ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);
 ctx.strokeStyle=innerC;ctx.lineWidth=innerW;ctx.stroke();
 return true;
}
function drawRhineUpper3252(R,cx,cy,zf){
 if(zoom<.88)return;
 const ow=3.55*zf,iw=1.86*zf;
 for(let i=0;i<RHINE_UPPER_NODE_PAIRS3252.length;i+=2){
   drawFaceNodeEdge3252(
     RHINE_UPPER_NODE_PAIRS3252[i],RHINE_UPPER_NODE_PAIRS3252[i+1],
     R,cx,cy,ow,'rgba(3,18,28,.52)',iw,'rgba(101,190,228,.99)'
   );
 }
}
function validateRhine3252(){
 let bad=0;
 for(let i=0;i<RHINE_UPPER_CELL_PAIRS3252.length;i+=2){
   const a=RHINE_UPPER_CELL_PAIRS3252[i],b=RHINE_UPPER_CELL_PAIRS3252[i+1];
   if(a<0||b<0)bad++;
 }
 const rin=MAP_RIVERS3242.find(r=>r.n==='Rin');
 const oldNodes=rin?edgePathNodes3242(rin):[];
 const joinOk=oldNodes.length&&oldNodes[0]===RHINE_UPPER_NODE_PAIRS3252[RHINE_UPPER_NODE_PAIRS3252.length-1];
 return {bad,joinOk,segments:RHINE_UPPER_NODE_PAIRS3252.length/2};
}

// ---------- Rivers: much more legible, still screen-space thin ----------
drawTerrain3212=function(R,cx,cy){
 if(zoom<.86)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.18,.88+Math.log2(Math.max(1,zoom))*.075);

 // Mountains remain subordinate to rivers and labels.
 for(const sys of MOUNTAIN_NETWORKS3242){
   if(!physicalSystemVisible3242(sys,false))continue;
   const t=sys.tier||1,
     ow=(t===3?2.90:t===2?2.26:1.68)*zf,
     iw=(t===3?1.22:t===2?.90:.61)*zf,
     ic=t===3?'rgba(194,155,114,.87)':t===2?'rgba(176,140,103,.78)':'rgba(151,119,88,.62)';
   for(const id of sys.edges){
     if(drawnM.has(id))continue;drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,ow,'rgba(61,44,31,.62)',iw,ic);
   }
 }

 // Existing canonical rivers.
 for(const sys of MAP_RIVERS3242){
   if(!physicalSystemVisible3242(sys,true))continue;
   const nav=NAV_RIVER_NAMES3242.has(sys.n);
   const ow=(sys.branch?1.75:nav?3.30:2.58)*zf;
   const iw=(sys.branch?.78:nav?1.68:1.22)*zf;
   const ic=nav
     ?'rgba(98,184,222,.98)'
     :sys.branch?'rgba(105,169,197,.79)':'rgba(95,174,207,.91)';
   for(const id of sys.edges){
     if(drawnR.has(id))continue;drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,ow,'rgba(3,17,27,.48)',iw,ic);
   }
 }

 // New upstream Rhine joins the old canonical Rhine at the exact same node.
 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

