// Smarter route drawing: route colour communicates operational supply.
drawFronts3230=function(R,cx,cy,now){
 const L=loadLevel(MAX_GAME_LEVEL3233),C=L.centers;ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
 for(const f of activeFronts3230){
   if(!f.route||f.route.length<2)continue;
   ctx.beginPath();let st=false;
   for(const id of f.route){
     const j=id*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
     if(p[2]<.03){st=false;continue}
     if(!st){ctx.moveTo(p[0],p[1]);st=true}else ctx.lineTo(p[0],p[1]);
   }
   const sup=f.supply3253??70;
   ctx.setLineDash([5,4]);
   ctx.strokeStyle=sup<25?'rgba(238,105,83,.76)':sup<50?'rgba(232,190,85,.68)':f.kind==='war'?'rgba(255,105,114,.58)':'rgba(88,170,255,.52)';
   ctx.lineWidth=sup<25?1.65:1.3;ctx.stroke();ctx.setLineDash([]);
   if(f.target>=0){
     const j=f.target*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
     if(p[2]>.04){
       ctx.beginPath();ctx.arc(p[0],p[1],3.3+Math.sin(now*.008)*.7,0,Math.PI*2);
       ctx.fillStyle=encircledMask3254?.[f.target]?'#ffb05c':f.kind==='war'?'#ff6a72':'#58aaff';ctx.fill();
       if(encircledMask3254?.[f.target]){
         ctx.beginPath();ctx.arc(p[0],p[1],6.2,0,Math.PI*2);
         ctx.strokeStyle='rgba(255,166,84,.70)';ctx.lineWidth=1;ctx.stroke();
       }
     }
   }
 }
 ctx.restore();
};


