// 5. RIVER MOUTHS: DO NOT FOLLOW THE COASTLINE
// -----------------------------------------------------------------------------
const riverMouthGeometryCache3254=new Map();

function riverMouthGeometry3254(sys){
 if(!sys||sys.branch||!sys.mouthExpected||sys.mouth<0)return null;
 if(riverMouthGeometryCache3254.has(sys.n))return riverMouthGeometryCache3254.get(sys.n);
 const L=loadLevel(MAX_GAME_LEVEL3233),nodes=edgePathNodes3242(sys);
 if(nodes.length<2){riverMouthGeometryCache3254.set(sys.n,null);return null}
 const edge=physicalEdge3242(sys.mouth);
 const shoreNode=nodes[nodes.length-2];
 let sea=-1;
 if(edge.a>=0&&L.land[edge.a]<0)sea=edge.a;
 else if(edge.b>=0&&L.land[edge.b]<0)sea=edge.b;
 if(sea<0){riverMouthGeometryCache3254.set(sys.n,null);return null}

 const F=L.faceCenters,C=L.centers,is=shoreNode*3,ic=sea*3;
 const shore=[F[is]/32767,F[is+1]/32767,F[is+2]/32767];
 const seaVec=[C[ic]/32767,C[ic+1]/32767,C[ic+2]/32767];
 const end=slerp3212(shore,seaVec,.30);
 const g={shore,end,shoreNode,sea,mouth:sys.mouth};
 riverMouthGeometryCache3254.set(sys.n,g);return g;
}
function drawSmoothMouth3254(sys,R,cx,cy,outerW,outerC,innerW,innerC){
 const g=riverMouthGeometry3254(sys);if(!g)return false;
 const a=projectVec(g.shore[0],g.shore[1],g.shore[2],R,cx,cy),
       b=projectVec(g.end[0],g.end[1],g.end[2],R,cx,cy);
 if(a[2]<.015||b[2]<.015)return false;
 ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
 ctx.strokeStyle=outerC;ctx.lineWidth=outerW*1.08;ctx.stroke();
 ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
 ctx.strokeStyle=innerC;ctx.lineWidth=innerW*1.12;ctx.stroke();

 // Small open-water flare at large zoom, enough to read as a mouth/delta
 // without inventing extra river branches.
 if(zoom>2.2){
   ctx.beginPath();ctx.arc(b[0],b[1],Math.max(.8,innerW*.72),0,Math.PI*2);
   ctx.fillStyle=innerC;ctx.fill();
 }
 return true;
}

// Final physical-network renderer.  Main rivers omit their last coastal edge;
// instead they leave the coast directly towards the adjacent sea cell.
drawTerrain3212=function(R,cx,cy){
 if(zoom<.86)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.18,.88+Math.log2(Math.max(1,zoom))*.075);

 for(const sys of MOUNTAIN_NETWORKS3242){
   if(!physicalSystemVisible3242(sys,false))continue;
   const t=sys.tier||1,
     ow=(t===3?2.90:t===2?2.26:1.68)*zf,
     iw=(t===3?1.22:t===2?.90:.61)*zf,
     ic=t===3?'rgba(194,155,114,.87)':t===2?'rgba(176,140,103,.78)':'rgba(151,119,88,.62)';
   for(const id of sys.edges){
     if(drawnM.has(id))continue;drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,ow,'rgba(61,44,31,.62)',iw,ic);
   }
 }

 for(const sys of MAP_RIVERS3242){
   if(!physicalSystemVisible3242(sys,true))continue;
   const nav=NAV_RIVER_NAMES3242.has(sys.n);
   const ow=(sys.branch?1.75:nav?3.30:2.58)*zf;
   const iw=(sys.branch?.78:nav?1.68:1.22)*zf;
   const ic=nav?'rgba(98,184,222,.98)':sys.branch?'rgba(105,169,197,.79)':'rgba(95,174,207,.91)';

   for(const id of sys.edges){
     if(!sys.branch&&sys.mouthExpected&&id===sys.mouth)continue;
     if(drawnR.has(id))continue;drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,ow,'rgba(3,17,27,.48)',iw,ic);
   }
   if(!sys.branch&&sys.mouthExpected){
     if(!drawSmoothMouth3254(sys,R,cx,cy,ow,'rgba(3,17,27,.48)',iw,ic)){
       // Fallback preserves the canonical network if a mouth lacks sea geometry.
       drawCanonicalEdge3242(sys.mouth,R,cx,cy,ow,'rgba(3,17,27,.48)',iw,ic);
     }
   }
 }

 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

function validateRiverMouths3254(){
 let corrected=0,fallback=0;
 for(const r of MAP_RIVERS3242){
   if(r.branch||!r.mouthExpected)continue;
   if(riverMouthGeometry3254(r))corrected++;else fallback++;
 }
 return {corrected,fallback};
}


