// -----------------------------------------------------------------------------
// 3. CONTINUOUS FRONT SECTORS
// -----------------------------------------------------------------------------
let frontierMask3255=null;
let frontierSector3255=null;
let frontierEnemy3255=null;
let frontierHostileN3255=null;
let frontQueue3255=null;
let frontVisualDirty3255=true;
let frontVisualTimer3255=0;
let frontVisualBuildMs3255=0;
let frontSectors3255=[];
let breakthroughCells3255=[];

function frontEnemyAtWar3255(o){
 return o>0&&relations3220[o]===-1;
}
function ensureFrontArrays3255(){
 const n=owner6.length;
 if(frontierMask3255&&frontierMask3255.length===n)return;
 frontierMask3255=new Uint8Array(n);
 frontierSector3255=new Int16Array(n);frontierSector3255.fill(-1);
 frontierEnemy3255=new Int16Array(n);frontierEnemy3255.fill(-1);
 frontierHostileN3255=new Uint8Array(n);
 frontQueue3255=new Int32Array(n);
}
function scheduleFrontVisualRebuild3255(){
 frontVisualDirty3255=true;
 if(frontVisualTimer3255)return;
 frontVisualTimer3255=setTimeout(()=>{
   frontVisualTimer3255=0;
   if(frontVisualDirty3255)rebuildFrontSectors3255();
 },280);
}
function rebuildFrontSectors3255(){
 ensureFrontArrays3255();
 const t0=performance.now(),L=loadLevel(MAX_GAME_LEVEL3233),n=L.n;
 frontierMask3255.fill(0);frontierSector3255.fill(-1);frontierEnemy3255.fill(-1);frontierHostileN3255.fill(0);
 breakthroughCells3255=[];

 // First pass: player frontier cells and hostile penetration candidates.
 for(let i=0;i<n;i++){
   const own=owner6[i],s=L.offsets[i],e=L.offsets[i+1];
   if(own===0){
     // Max 6 neighbours: count the dominant enemy without allocating
     // a temporary array for every owned cell.
     let total=0,bestEnemy=-1,bestN=0;
     const localEnemy3255=[-1,-1,-1,-1,-1,-1],
           localCount3255=[0,0,0,0,0,0];
     let localUsed3255=0;
     for(let k=s;k<e;k++){
       const v=L.edgeNbr[k],vo=v>=0?owner6[v]:-1;
       if(!frontEnemyAtWar3255(vo))continue;
       total++;
       let slot=-1;
       for(let q=0;q<localUsed3255;q++)if(localEnemy3255[q]===vo){slot=q;break}
       if(slot<0){slot=localUsed3255++;localEnemy3255[slot]=vo}
       const c=++localCount3255[slot];
       if(c>bestN){bestN=c;bestEnemy=vo}
     }
     if(total){
       frontierMask3255[i]=1;frontierEnemy3255[i]=bestEnemy;
       frontierHostileN3255[i]=total;
     }
   }else if(frontEnemyAtWar3255(own)){
     let playerN=0;
     for(let k=s;k<e;k++){
       const v=L.edgeNbr[k];
       if(v>=0&&owner6[v]===0)playerN++;
     }
     if(playerN>=3&&!encircledMask3254?.[i])breakthroughCells3255.push(i);
   }
 }

 // Second pass: connected frontier sectors, split by dominant enemy.
 const sectors=[];
 for(let start=0;start<n;start++){
   if(!frontierMask3255[start]||frontierSector3255[start]>=0)continue;
   const enemy=frontierEnemy3255[start],id=sectors.length;
   let h=0,t=0,supplySum=0,salients=0;
   frontQueue3255[t++]=start;frontierSector3255[start]=id;

   while(h<t){
     const u=frontQueue3255[h++];
     supplySum+=supplyPct3220(u);
     if(frontierHostileN3255[u]>=3)salients++;
     const s=L.offsets[u],e=L.offsets[u+1];
     for(let k=s;k<e;k++){
       const v=L.edgeNbr[k];
       if(v<0||!frontierMask3255[v]||frontierSector3255[v]>=0||frontierEnemy3255[v]!==enemy)continue;
       frontierSector3255[v]=id;frontQueue3255[t++]=v;
     }
   }

   sectors.push({
     id,enemy,size:t,
     supply:t?Math.round(supplySum/t):0,
     salients
   });
 }
 frontSectors3255=sectors;
 frontVisualDirty3255=false;
 frontVisualBuildMs3255=performance.now()-t0;
 needsRender=true;
}

// Any ownership/topology change that already invalidates encirclements also
// invalidates the continuous front.
const _markEncirclementDirtyFront3255=markEncirclementDirty3254;
markEncirclementDirty3254=function(){
 _markEncirclementDirtyFront3255();
 scheduleFrontVisualRebuild3255();
};

const _setRelationFront3255=setRelation3220;
setRelation3220=function(f,val){
 _setRelationFront3255(f,val);
 scheduleFrontVisualRebuild3255();
};

function activeRouteCells3255(){
 const s=new Set();
 for(const f of activeFronts3230){
   if(f.route)for(const c of f.route)s.add(c);
   if(f.target>=0)s.add(f.target);
 }
 return s;
}
function cellNearActiveRoute3255(cell,active,L){
 if(active.has(cell))return true;
 const s=L.offsets[cell],e=L.offsets[cell+1];
 for(let k=s;k<e;k++)if(active.has(L.edgeNbr[k]))return true;
 return false;
}
function frontSegmentState3255(playerCell,enemyCell,active,L){
 if(encircledMask3254?.[playerCell]||encircledMask3254?.[enemyCell])return 'pocket';
 if(cellNearActiveRoute3255(playerCell,active,L)||cellNearActiveRoute3255(enemyCell,active,L))return 'active';
 const sp=supplyPct3220(playerCell);
 if(sp<42)return 'supply';
 if(frontierHostileN3255?.[playerCell]>=3)return 'salient';
 return 'stable';
}
function frontStateStyle3255(state,strong){
 if(state==='pocket')return ['rgba(239,104,84,.96)',strong?2.85:1.45];
 if(state==='active')return ['rgba(101,200,255,.98)',strong?3.15:1.65];
 if(state==='supply')return ['rgba(231,200,102,.95)',strong?2.55:1.35];
 if(state==='salient')return ['rgba(255,173,92,.94)',strong?2.55:1.35];
 return ['rgba(166,184,199,.80)',strong?1.75:.95];
}

function drawContinuousFront3255(R,cx,cy,now){
 if(playerCountry<0||!frontierMask3255)return;
 if(frontVisualDirty3255)scheduleFrontVisualRebuild3255();

 const L=currentLevel,F=L.faceCenters,O=L.offsets,A=L.adj,N=L.edgeNbr;
 const detailed=currentKey===MAX_GAME_LEVEL3233;
 const strong=mapMode3252==='fronts';
 const active=activeRouteCells3255();

 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 // Visible shared edges only.
 for(const d of drawn){
   const i=d[0],oi=displayOwner(currentKey,i);
   if(oi!==0)continue;
   const s=O[i],e=O[i+1];
   for(let k=s;k<e;k++){
     const n=N[k];if(n<0||n<i)continue;
     const on=displayOwner(currentKey,n);
     if(!frontEnemyAtWar3255(on))continue;

     const fiA=A[k],fiB=A[s+((k-s+1)%(e-s))];
     const a=projectVec(F[fiA*3]/32767,F[fiA*3+1]/32767,F[fiA*3+2]/32767,R,cx,cy);
     const b=projectVec(F[fiB*3]/32767,F[fiB*3+1]/32767,F[fiB*3+2]/32767,R,cx,cy);
     if(a[2]<-.02&&b[2]<-.02)continue;

     let state='stable';
     if(detailed)state=frontSegmentState3255(i,n,active,L);
     const [col,w]=frontStateStyle3255(state,strong);
     ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
     ctx.strokeStyle=col;ctx.lineWidth=w;ctx.stroke();
   }
 }

 // Detailed F-mode: sector labels and possible local rupture points.
 if(strong&&detailed&&adaptiveDetail3255===0&&zoom>=2.15){
   const sums=new Map();
   for(const d of drawn){
     const c=d[0],sid=frontierSector3255[c];
     if(sid<0)continue;
     let q=sums.get(sid);
     if(!q){q={x:0,y:0,n:0,active:false};sums.set(sid,q)}
     q.x+=d[1];q.y+=d[2];q.n++;
     if(cellNearActiveRoute3255(c,active,L))q.active=true;
   }

   ctx.textAlign='center';ctx.textBaseline='middle';
   let labels=0;
   for(const [sid,q] of sums){
     if(labels++>=10||q.n<2)continue;
     const sec=frontSectors3255[sid];if(!sec)continue;
     const x=q.x/q.n,y=q.y/q.n;
     const txt=`F${sid+1} · ${q.active?'ACTIVO':sec.supply<42?'SUM. BAJO':'ESTABLE'} · ${sec.supply}%`;
     ctx.font='800 6.6px system-ui';
     ctx.lineWidth=2.4;ctx.strokeStyle='rgba(2,7,12,.88)';ctx.strokeText(txt,x,y);
     ctx.fillStyle=q.active?'#9adeff':sec.supply<42?'#ead17d':'#cfdae3';ctx.fillText(txt,x,y);
   }

   // Enemy cells touched from >=3 player sides are good local breakthrough /
   // pocket-closing opportunities. Only visible candidates are marked.
   if(zoom>=3.0){
     const C=L.centers;let marks=0;
     for(const c of breakthroughCells3255){
       if(marks>=18)break;
       const j=c*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
       if(p[2]<.05||p[0]<0||p[0]>vw||p[1]<0||p[1]>vh)continue;
       const r=3.2+Math.sin(now*.006+c)*.45;
       ctx.beginPath();
       ctx.moveTo(p[0],p[1]-r);ctx.lineTo(p[0]+r,p[1]);ctx.lineTo(p[0],p[1]+r);ctx.lineTo(p[0]-r,p[1]);ctx.closePath();
       ctx.strokeStyle='rgba(255,173,92,.88)';ctx.lineWidth=1;ctx.stroke();marks++;
     }
   }
 }

 ctx.restore();
}


// -----------------------------------------------------------------------------
// 4. ROUTES THAT EXPLAIN THEMSELVES VISUALLY
// -----------------------------------------------------------------------------
const _drawFrontsSmartBase3255=drawFronts3230;
drawFronts3230=function(R,cx,cy,now){
 if(mapMode3252!=='fronts')return _drawFrontsSmartBase3255(R,cx,cy,now);

 const L=loadLevel(MAX_GAME_LEVEL3233),C=L.centers;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 for(const f of activeFronts3230){
   const path=f.route;if(!path||path.length<2)continue;
   const sup=f.supply3253??70;

   for(let k=1;k<path.length;k++){
     const a=path[k-1],b=path[k],ia=a*3,ib=b*3;
     const p=projectVec(C[ia]/32767,C[ia+1]/32767,C[ia+2]/32767,R,cx,cy);
     const q=projectVec(C[ib]/32767,C[ib+1]/32767,C[ib+2]/32767,R,cx,cy);
     if(p[2]<.03||q[2]<.03)continue;

     const road=roadCross3230(a,b),river=riverCross3230(a,b),tk=terrainKey3250(b);
     let col;
     if(sup<25)col='rgba(239,104,84,.96)';
     else if(road)col='rgba(96,224,179,.96)';
     else if(river)col='rgba(96,190,229,.96)';
     else if(tk==='mountain'||tk==='highmountain')col='rgba(234,164,92,.96)';
     else col=f.kind==='war'?'rgba(255,129,137,.86)':'rgba(114,190,255,.86)';

     ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);
     ctx.strokeStyle='rgba(2,8,14,.72)';ctx.lineWidth=3.15;ctx.stroke();
     ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);
     ctx.strokeStyle=col;ctx.lineWidth=1.55;ctx.stroke();
   }

   if(f.target>=0){
     const j=f.target*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
     if(p[2]>.04){
       ctx.beginPath();ctx.arc(p[0],p[1],3.5+Math.sin(now*.008)*.7,0,Math.PI*2);
       ctx.fillStyle=encircledMask3254?.[f.target]?'#ffad5c':f.kind==='war'?'#ff7882':'#65c8ff';ctx.fill();
     }
   }
 }
 ctx.restore();
};


// Put the continuous front over the map geometry, but retain infrastructure and
// icons. It follows shared hex edges and therefore never "floats" across cells.
const _drawInfrastructureFrontBase3255=drawInfrastructure3212;
drawInfrastructure3212=function(R,cx,cy,now){
 const v=_drawInfrastructureFrontBase3255(R,cx,cy,now);
 drawContinuousFront3255(R,cx,cy,now);
 return v;
};


// -----------------------------------------------------------------------------
// 5. RIVERS STOP EXACTLY AT THE COAST LIMIT
// -----------------------------------------------------------------------------
drawTerrain3212=function(R,cx,cy){
 if(zoom<.86)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.18,.88+Math.log2(Math.max(1,zoom))*.075);

 // On slow mobile, remove only minor mountain chains. Major relief stays.
 for(const sys of MOUNTAIN_NETWORKS3242){
   if(!physicalSystemVisible3242(sys,false))continue;
   const t=sys.tier||1;
   if(coarsePointer3255&&adaptiveDetail3255>=1&&t===1)continue;

   const ow=(t===3?2.90:t===2?2.26:1.68)*zf,
         iw=(t===3?1.22:t===2?.90:.61)*zf,
         ic=t===3?'rgba(194,155,114,.87)':t===2?'rgba(176,140,103,.78)':'rgba(151,119,88,.62)';
   for(const id of sys.edges){
     if(drawnM.has(id))continue;drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,ow,'rgba(61,44,31,.62)',iw,ic);
   }
 }

 for(const sys of MAP_RIVERS3242){
   if(!physicalSystemVisible3242(sys,true))continue;
   if(coarsePointer3255&&adaptiveDetail3255>=2&&sys.branch)continue;

   const nav=NAV_RIVER_NAMES3242.has(sys.n);
   const ow=(sys.branch?1.75:nav?3.30:2.58)*zf;
   const iw=(sys.branch?.78:nav?1.68:1.22)*zf;
   const ic=nav?'rgba(98,184,222,.98)':sys.branch?'rgba(105,169,197,.79)':'rgba(95,174,207,.91)';

   for(const id of sys.edges){
     // The mouth edge IS the coastline edge. Drawing it creates the artificial
     // bend along the coast. We stop at its first vertex instead; the previous
     // river segment already reaches that exact coastline limit.
     if(!sys.branch&&sys.mouthExpected&&id===sys.mouth)continue;
     if(drawnR.has(id))continue;drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,ow,'rgba(3,17,27,.48)',iw,ic);
   }
 }

 // Upstream Rhine added in v3.25.2 remains unchanged.
 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

validateRiverMouths3254=function(){
 let stopped=0;
 for(const r of MAP_RIVERS3242)if(!r.branch&&r.mouthExpected&&r.mouth>=0)stopped++;
 return {corrected:stopped,fallback:0};
};


