// ================= /v3.25.5 =================



// ================= v3.26.0 · STRATEGIC AI =================
//
// The bots no longer choose the war one random border hex at a time.
//
// Strategic layer:
// - one shared world snapshot for all bots, built only every few campaign
//   seconds and never every frame;
// - each faction adopts a posture: expansion / offensive / defense / recovery /
//   breakout / containment;
// - objectives value capitals, cities, ports, industry, roads, weak supply and
//   encircled pockets;
// - manoeuvres: frontal attack, breakthrough, pincer, pocket closure, breakout,
//   counterattack;
// - faction personalities alter aggression, reserves, infrastructure and naval
//   priorities;
// - bots hold a real reserve and avoid major attacks from badly supplied areas;
// - defensive bots reinforce threatened sectors and capitals;
// - bots can build short road links from a front toward their capital;
// - plans are transient and rebuilt after major map changes, so old saves remain
//   compatible.
//
// Performance:
// - only ONE world scan serves all seven bots;
// - frontier samples are capped (no giant JS arrays);
// - strategic thinking has both campaign-time and wall-time throttles;
// - tactical execution works only on sampled/near-objective frontier cells;
// - no strategic search runs in render().

const AI_FRONTIER_SAMPLE3260=300;
const AI_ENC_SAMPLE3260=80;
const AI_STRATEGIC_CAMPAIGN_PERIOD3260=9;
const AI_STRATEGIC_WALL_MIN3260=2600;

const AI_ROLE_PROFILE3260={
 balanced:   {reserve:.17,attack:1.00,expand:1.00,fort:.95,industry:1.00,naval:.75},
 aggressive: {reserve:.12,attack:1.24,expand:.88,fort:.72,industry:.80,naval:.60},
 growth:     {reserve:.15,attack:.92,expand:1.28,fort:.78,industry:1.20,naval:.75},
 defense:    {reserve:.22,attack:.78,expand:.72,fort:1.32,industry:1.02,naval:.65},
 naval:      {reserve:.16,attack:.98,expand:.90,fort:.86,industry:.95,naval:1.40}
};

let aiStrategicState3260=[];
let aiSnapshot3260=null;
let aiSnapshotDirty3260=true;
let aiLastStrategicCampaign3260=-1e9;
let aiLastStrategicWall3260=-1e9;
let aiSnapshotBuildMs3260=0;
let aiThinkBuildMs3260=0;
let aiExecMs3260=0;
let aiExecSamples3260=0;
let aiPlanSerial3260=1;

function blankAIState3260(f){
 return {
   faction:f,serial:0,stance:'idle',maneuver:'hold',objective:-1,objectiveOwner:-2,
   source:-1,secondary:-1,score:0,reserveFloor:55,supply:100,
   targetEnemy:-1,reason:'sin plan',nextThink:0,momentum:0,
   successes:0,failures:0,actions:0,lastActionCampaign:-1e9
 };
}
function resetAIStrategy3260(){
 aiStrategicState3260=Array.from({length:FACTIONS3230.length},(_,f)=>blankAIState3260(f));
 aiSnapshot3260=null;aiSnapshotDirty3260=true;
 aiLastStrategicCampaign3260=-1e9;aiLastStrategicWall3260=-1e9;
}
resetAIStrategy3260();

function aiMarkDirty3260(){
 aiSnapshotDirty3260=true;
}

// Piggyback on the topology invalidation already used by fronts/cercos.
const _markEncirclementAIBase3260=markEncirclementDirty3254;
markEncirclementDirty3254=function(){
 _markEncirclementAIBase3260();
 aiMarkDirty3260();
};

// Relation changes involving the player can instantly invalidate bot plans.
const _setRelationAIBase3260=setRelation3220;
setRelation3220=function(f,val){
 _setRelationAIBase3260(f,val);
 if(f>0){
   const st=aiStrategicState3260[f];
   if(st)st.nextThink=0;
   aiMarkDirty3260();
 }
};


// -----------------------------------------------------------------------------
// 1. SHARED WORLD SNAPSHOT
// -----------------------------------------------------------------------------
function addSample3260(arr,cell,seen,cap){
 if(arr.length<cap){arr.push(cell);return}
 // Deterministic low-allocation reservoir-like replacement.
 const j=(cell*1103515245+seen*12345)>>>0;
 const idx=j%(seen+1);
 if(idx<cap)arr[idx]=cell;
}
function aiCapitalThreat3260(f,frontier){
 const cap=capitals[f];
 if(cap<0||owner6[cap]!==f)return 99;
 let best=999;
 const lim=Math.min(frontier.length,120);
 for(let i=0;i<lim;i++){
   const c=frontier[i];
   const d=angularHeuristic3254(cap,c);
   if(d<best)best=d;
 }
 return best;
}
function rebuildAISnapshot3260(){
 const t0=performance.now(),L=loadLevel(MAX_GAME_LEVEL3233),n=L.n,F=FACTIONS3230.length;
 const territory=new Int32Array(F),frontierCount=new Int32Array(F),
       neutralBorder=new Int32Array(F),hostileBorder=new Int32Array(F),
       playerBorder=new Int32Array(F),encCount=new Int32Array(F);
 const frontier=Array.from({length:F},()=>[]);
 const encircled=Array.from({length:F},()=>[]);
 const frontierSeen=new Int32Array(F),encSeen=new Int32Array(F);

 for(let i=0;i<n;i++){
   const f=owner6[i];
   if(f<0||f>=F)continue;
   territory[f]++;

   if(encircledMask3254?.[i]){
     encCount[f]++;encSeen[f]++;
     addSample3260(encircled[f],i,encSeen[f],AI_ENC_SAMPLE3260);
   }

   let border=false,neutral=false,hostile=false,player=false;
   const s=L.offsets[i],e=L.offsets[i+1];
   for(let k=s;k<e;k++){
     const v=L.edgeNbr[k];if(v<0)continue;
     const o=owner6[v];
     if(o===f)continue;
     if(L.land[v]<0)continue;
     border=true;
     if(o<0)neutral=true;
     else{
       hostile=true;
       if(o===0)player=true;
     }
   }
   if(border){
     frontierCount[f]++;
     if(neutral)neutralBorder[f]++;
     if(hostile)hostileBorder[f]++;
     if(player)playerBorder[f]++;
     frontierSeen[f]++;
     addSample3260(frontier[f],i,frontierSeen[f],AI_FRONTIER_SAMPLE3260);
   }
 }

 const cities=Array.from({length:F},()=>[]),industries=Array.from({length:F},()=>[]),ports=Array.from({length:F},()=>[]);
 for(const c of cities3212){const f=owner6[c];if(f>=0&&f<F&&cities[f].length<100)cities[f].push(c)}
 for(const c of industries3212){const f=owner6[c];if(f>=0&&f<F&&industries[f].length<100)industries[f].push(c)}
 for(const c of ports3212){const f=owner6[c];if(f>=0&&f<F&&ports[f].length<100)ports[f].push(c)}

 const capThreat=new Float32Array(F);
 for(let f=1;f<F;f++)capThreat[f]=aiCapitalThreat3260(f,frontier[f]);

 aiSnapshot3260={
   territory,frontierCount,neutralBorder,hostileBorder,playerBorder,encCount,
   frontier,encircled,cities,industries,ports,capThreat,
   campaign:campaignSeconds3230
 };
 aiSnapshotDirty3260=false;
 aiSnapshotBuildMs3260=performance.now()-t0;
 return aiSnapshot3260;
}


// -----------------------------------------------------------------------------
// 2. LOCAL BOT LOGISTICS / STRATEGIC VALUE
// -----------------------------------------------------------------------------
function aiRoadDegree3260(cell){
 const L=loadLevel(MAX_GAME_LEVEL3233),s=L.offsets[cell],e=L.offsets[cell+1];
 let n=0;
 for(let k=s;k<e;k++){
   const v=L.edgeNbr[k];
   if(v>=0&&roadEdgeSet3212.has(edgeKey3212(cell,v)))n++;
 }
 return n;
}
function aiLocalSupply3260(f,cell){
 if(cell<0||owner6[cell]!==f)return 0;
 if(encircledMask3254?.[cell]){
   let p=18;
   if(ports3212.has(cell))p+=18;
   if(cities3212.has(cell))p+=8;
   return Math.min(48,p);
 }
 const cap=capitals[f];
 let dist=cap>=0&&owner6[cap]===f?angularHeuristic3254(cap,cell):42;
 let p=100-dist*1.55;
 p+=Math.min(18,aiRoadDegree3260(cell)*6);
 if(cities3212.has(cell))p+=8;
 if(ports3212.has(cell))p+=10;
 if(terrainKey3250(cell)==='desert'||terrainKey3250(cell)==='tundra')p-=7;
 if(terrainKey3250(cell)==='mountain')p-=8;
 if(terrainKey3250(cell)==='highmountain')p-=14;
 return Math.max(8,Math.min(100,Math.round(p)));
}
function aiOwnNeighbours3260(f,cell){
 const L=loadLevel(MAX_GAME_LEVEL3233),s=L.offsets[cell],e=L.offsets[cell+1];
 let n=0;
 for(let k=s;k<e;k++){const v=L.edgeNbr[k];if(v>=0&&owner6[v]===f)n++}
 return n;
}
function aiEnemyNeighbours3260(f,cell){
 const L=loadLevel(MAX_GAME_LEVEL3233),s=L.offsets[cell],e=L.offsets[cell+1];
 let n=0;
 for(let k=s;k<e;k++){const v=L.edgeNbr[k];if(v>=0&&owner6[v]>=0&&owner6[v]!==f)n++}
 return n;
}
function aiTargetAllowed3260(f,target){
 const o=owner6[target];
 if(o===f)return false;
 if(o===0&&relations3220[f]>=2)return false; // respect NAP/alliance with player
 return true;
}
function aiStrategicValue3260(f,src,target,stance,maneuver,objective=-1){
 if(target<0||!aiTargetAllowed3260(f,target))return -1e9;
 const def=owner6[target],tp=terrainProfile3250(target);
 const road=roadCross3230(src,target),river=riverCross3230(src,target);
 let sc=0;

 // Physical route quality.
 sc+=tp.move*2.2-(tp.defense-1)*2.4;
 if(road)sc+=1.75;
 if(river)sc-=.65;
 if(terrainKey3250(target)==='highmountain'&&!road)sc-=2.6;

 // Strategic assets.
 if(capitals.includes(target))sc+=10.5;
 sc+=(cityLevel3230[target]||0)*3.0;
 sc+=(industryLevel3230[target]||0)*2.1;
 if(ports3212.has(target))sc+=2.7;
 sc+=aiRoadDegree3260(target)*.55;
 sc-=(forts3212[target]||0)*1.8;

 // Neutral expansion vs war.
 if(def<0)sc+=stance==='expansion'?5.2:1.0;
 else sc+=stance==='offensive'||stance==='containment'||stance==='recovery'?3.0:1.1;

 // Existing pocket weakness is a natural closing target.
 if(encircledMask3254?.[target]){
   const age=encircledAge3254[target]||0;
   sc+=3.6+Math.min(3,age*.06);
 }

 // Manoeuvre geometry.
 const ownN=aiOwnNeighbours3260(f,target);
 if(maneuver==='pincer')sc+=ownN*1.35;
 if(maneuver==='encircle')sc+=ownN*.95+aiRoadDegree3260(target)*.35;
 if(maneuver==='breakthrough'){if(road)sc+=1.8;sc-=(forts3212[target]||0)*.7}
 if(maneuver==='breakout')sc+=ownN*.45;
 if(maneuver==='counterattack')sc+=capitals.includes(src)?1.8:0;

 // Stay focused on the selected operational objective.
 if(objective>=0&&target!==objective){
   sc-=Math.min(7,angularHeuristic3254(target,objective)*.12);
 }

 // Player diplomacy: peace/trade is less attractive than an existing war.
 if(def===0){
   if(relations3220[f]===-1)sc+=2.2;
   else if(relations3220[f]===1)sc-=3.0;
   else sc-=1.1;
 }

 return sc;
}


// -----------------------------------------------------------------------------
// 3. PLAN SELECTION
// -----------------------------------------------------------------------------
function chooseAIManeuver3260(f,src,target,stance){
 if(src<0||target<0)return 'hold';
 if(stance==='breakout')return 'breakout';
 if(stance==='defense')return 'counterattack';
 if(encircledMask3254?.[target])return 'encircle';

 const ownN=aiOwnNeighbours3260(f,target);
 if(ownN>=3)return 'pincer';
 if(roadCross3230(src,target)&&(forts3212[target]||0)<=1)return 'breakthrough';
 if(aiRoadDegree3260(target)>=2&&(cities3212.has(target)||ports3212.has(target)))return 'encircle';
 return 'frontal';
}
function findBestAICandidate3260(f,snap,stance,objectiveHint=-1,forcedOwner=null){
 const L=loadLevel(MAX_GAME_LEVEL3233),samples=snap.frontier[f];
 let bestSrc=-1,best=-1,bestSc=-1e9,seen=0;

 for(let ii=0;ii<samples.length;ii++){
   const src=samples[ii];if(owner6[src]!==f)continue;
   const supply=aiLocalSupply3260(f,src);
   const s=L.offsets[src],e=L.offsets[src+1];
   for(let k=s;k<e;k++){
     const target=L.edgeNbr[k];
     if(target<0||L.land[target]<0||!aiTargetAllowed3260(f,target))continue;
     const o=owner6[target];
     if(forcedOwner!=null&&o!==forcedOwner)continue;
     if(stance==='expansion'&&o>=0&&snap.neutralBorder[f]>0)continue;

     const man=chooseAIManeuver3260(f,src,target,stance);
     let sc=aiStrategicValue3260(f,src,target,stance,man,objectiveHint);

     // Don't launch a major attack from a logistical dead end.
     if(o>=0&&supply<35)sc-=5.5;
     else if(supply<55)sc-=2.2;
     else if(supply>78)sc+=1.0;

     // Small deterministic noise prevents every faction from making identical
     // choices without requiring a huge random search.
     sc+=(((src*31+target*17+f*13+aiPlanSerial3260)%29)-14)*.035;
     seen++;
     if(sc>bestSc){bestSc=sc;best=target;bestSrc=src}
   }
 }
 return {src:bestSrc,target:best,score:bestSc,seen};
}

function aiHistoricRecoveryTarget3260(f,snap){
 const h=historicCapital3230[f];
 if(h<0||owner6[h]===f)return -1;
 // Only call it a recovery objective while the old capital is reasonably close
 // to the current sampled frontier.
 let best=999;
 for(const c of snap.frontier[f]){
   const d=angularHeuristic3254(c,h);if(d<best)best=d;
 }
 return best<26?h:-1;
}

function aiPlanFaction3260(f,snap){
 const fac=FACTIONS3230[f],rp=AI_ROLE_PROFILE3260[fac.role]||AI_ROLE_PROFILE3260.balanced;
 const old=aiStrategicState3260[f]||blankAIState3260(f);
 const max=Math.max(1,economyRate3230(f).max);
 const reserveFloor=Math.max(48,Math.round(max*rp.reserve));
 const troops=troops3230[f];
 const ownPocket=snap.encCount[f]>0;
 const capThreat=snap.capThreat[f];
 const historic=aiHistoricRecoveryTarget3260(f,snap);
 const atWarPlayer=relations3220[f]===-1&&snap.playerBorder[f]>0;

 let stance='offensive',reason='presión sobre el frente';

 if(ownPocket){
   stance='breakout';reason='abrir una bolsa propia';
 }else if(capThreat<12||troops<reserveFloor*1.10){
   stance='defense';reason=capThreat<12?'defender la capital':'reconstituir reservas';
 }else if(historic>=0){
   stance='recovery';reason='recuperar la capital histórica';
 }else if(snap.neutralBorder[f]>Math.max(2,snap.hostileBorder[f]*.45)&&
         (fac.role==='growth'||troops<max*.55)){
   stance='expansion';reason='expandirse por territorio libre';
 }else if(atWarPlayer&&fac.role==='defense'){
   stance='containment';reason='contener al jugador';
 }else if(atWarPlayer){
   stance='offensive';reason='presionar al jugador';
 }else if(fac.role==='aggressive'){
   stance='offensive';reason='buscar ruptura';
 }else if(fac.role==='naval'&&snap.ports[f].length){
   stance='offensive';reason='asegurar nodos costeros';
 }

 let forcedOwner=null,objHint=-1;
 if(stance==='recovery')objHint=historic;
 if(stance==='containment'||(stance==='offensive'&&atWarPlayer))forcedOwner=0;

 // Breakout: start specifically from a sampled isolated cell if possible.
 let cand;
 if(stance==='breakout'&&snap.encircled[f].length){
   const L=loadLevel(MAX_GAME_LEVEL3233);
   let best={src:-1,target:-1,score:-1e9};
   for(const src of snap.encircled[f]){
     if(owner6[src]!==f)continue;
     const s=L.offsets[src],e=L.offsets[src+1];
     for(let k=s;k<e;k++){
       const t=L.edgeNbr[k];
       if(t<0||L.land[t]<0||!aiTargetAllowed3260(f,t))continue;
       let sc=aiStrategicValue3260(f,src,t,stance,'breakout',-1);
       // Prefer a corridor touching non-encircled friendly territory.
       const ts=L.offsets[t],te=L.offsets[t+1];let relief=0;
       for(let q=ts;q<te;q++){
         const n=L.edgeNbr[q];
         if(n>=0&&owner6[n]===f&&!encircledMask3254?.[n])relief++;
       }
       sc+=relief*4;
       if(sc>best.score)best={src,target:t,score:sc};
     }
   }
   cand=best;
 }else{
   cand=findBestAICandidate3260(f,snap,stance,objHint,forcedOwner);
   // A strict player target can disappear after a local conquest. Fall back to
   // the best legal border while keeping the same strategic posture.
   if(cand.target<0)cand=findBestAICandidate3260(f,snap,stance,objHint,null);
 }

 const maneuver=chooseAIManeuver3260(f,cand.src,cand.target,stance);
 const supply=cand.src>=0?aiLocalSupply3260(f,cand.src):0;
 const state={
   faction:f,serial:aiPlanSerial3260++,stance,maneuver,
   objective:cand.target,objectiveOwner:cand.target>=0?owner6[cand.target]:-2,
   source:cand.src,secondary:-1,score:cand.score||0,reserveFloor,supply,
   targetEnemy:cand.target>=0?owner6[cand.target]:-1,
   reason,nextThink:campaignSeconds3230+AI_STRATEGIC_CAMPAIGN_PERIOD3260+
     ((f*2+aiPlanSerial3260)%4),
   momentum:Math.max(0,Math.min(4,old.momentum||0)),
   successes:old.successes||0,failures:old.failures||0,actions:old.actions||0,
   lastActionCampaign:old.lastActionCampaign||-1e9
 };

 // Pincer gets a second nearby target from a different source when possible.
 if(maneuver==='pincer'&&cand.target>=0){
   const L=loadLevel(MAX_GAME_LEVEL3233),s=L.offsets[cand.target],e=L.offsets[cand.target+1];
   let second=-1,secondSc=-1e9;
   for(let k=s;k<e;k++){
     const t=L.edgeNbr[k];
     if(t<0||owner6[t]===f||!aiTargetAllowed3260(f,t))continue;
     const sc=aiStrategicValue3260(f,cand.src,t,stance,'pincer',cand.target);
     if(sc>secondSc){secondSc=sc;second=t}
   }
   state.secondary=second;
 }

 aiStrategicState3260[f]=state;
 return state;
}

function strategicThink3260(force=false){
 const wall=performance.now();
 if(!force){
   if(campaignSeconds3230-aiLastStrategicCampaign3260<AI_STRATEGIC_CAMPAIGN_PERIOD3260&&
      !aiSnapshotDirty3260)return;
   if(wall-aiLastStrategicWall3260<AI_STRATEGIC_WALL_MIN3260)return;
 }
 const t0=performance.now();
 const snap=rebuildAISnapshot3260();
 for(let f=1;f<FACTIONS3230.length;f++){
   const st=aiStrategicState3260[f];
   if(force||!st||campaignSeconds3230>=st.nextThink||aiSnapshotDirty3260)aiPlanFaction3260(f,snap);
   else{
     // Even a still-valid plan gets refreshed if its objective/source vanished.
     if(st.objective<0||st.source<0||owner6[st.source]!==f||owner6[st.objective]===f)
       aiPlanFaction3260(f,snap);
   }
 }
 aiLastStrategicCampaign3260=campaignSeconds3230;
 aiLastStrategicWall3260=wall;
 aiThinkBuildMs3260=performance.now()-t0;
}


// -----------------------------------------------------------------------------
// 4. TACTICAL EXECUTION OF THE STRATEGIC PLAN
// -----------------------------------------------------------------------------
function aiDeclarePlayerWar3260(f){
 if(relations3220[f]>=2)return false;
 if(relations3220[f]!==-1){
   relations3220[f]=-1;
   toast(`${factionName3230(f)} declara la guerra`);
   updateFrontDock3220();renderSystems3220();
 }
 return true;
}
function aiAttackProbability3260(f,src,target,state){
 const def=owner6[target],tp=terrainProfile3250(target);
 const road=roadCross3230(src,target),river=riverCross3230(src,target);
 const supply=aiLocalSupply3260(f,src);
 const enc=!!encircledMask3254?.[target],age=enc?(encircledAge3254[target]||0):0;

 if(def<0){
   let p=.88+Math.min(.05,state.momentum*.012)-Math.max(0,1-tp.move)*.07;
   if(supply<35)p-=.11;
   if(road)p+=.03;
   return Math.max(.58,Math.min(.95,p));
 }

 const defender=Math.max(12,(troops3230[def]||120)*(enc?Math.max(.58,1-age*.009):1));
 let p=.27+(troops3230[f]/(troops3230[f]+defender))*.44;
 p+=FACTIONS3230[f].aggr*.055;
 p+=(supply-50)*.0015;
 p-=(tp.defense-1)*.18+(1-tp.attack)*.14;
 p-=(forts3212[target]||0)*.095*(enc?.60:1);
 if(river)p-=road?.015:.055;
 if(road)p+=.055;
 if(enc)p+=Math.min(.16,.065+age*.0025);

 if(state.maneuver==='breakthrough')p+=.035;
 else if(state.maneuver==='pincer')p+=Math.min(.07,aiOwnNeighbours3260(f,target)*.018);
 else if(state.maneuver==='encircle')p+=.03;
 else if(state.maneuver==='counterattack')p+=.018;
 else if(state.maneuver==='breakout')p+=.04;

 p+=Math.min(.055,state.momentum*.014);
 return Math.max(.055,Math.min(.90,p));
}
function findExecutionCandidate3260(f,state){
 const L=loadLevel(MAX_GAME_LEVEL3233),snap=aiSnapshot3260;
 let best={src:-1,target:-1,score:-1e9};

 // Objective source first, then sampled frontier. This creates real operational
 // concentration without allocating troops to thousands of cells.
 const sources=[];
 if(state.source>=0)sources.push(state.source);
 if(state.objective>=0){
   const s=L.offsets[state.objective],e=L.offsets[state.objective+1];
   for(let k=s;k<e;k++){
     const n=L.edgeNbr[k];if(n>=0&&owner6[n]===f)sources.push(n);
   }
 }
 const sample=snap?.frontier[f]||[];
 const stride=Math.max(1,Math.floor(sample.length/50));
 for(let i=(state.serial%stride);i<sample.length&&sources.length<72;i+=stride)sources.push(sample[i]);

 for(const src of sources){
   if(src<0||owner6[src]!==f)continue;
   const supply=aiLocalSupply3260(f,src);
   const s=L.offsets[src],e=L.offsets[src+1];
   for(let k=s;k<e;k++){
     const target=L.edgeNbr[k];
     if(target<0||L.land[target]<0||!aiTargetAllowed3260(f,target))continue;
     let sc=aiStrategicValue3260(f,src,target,state.stance,state.maneuver,state.objective);
     if(target===state.objective)sc+=5.5;
     if(target===state.secondary)sc+=2.8;
     if(owner6[target]>=0&&supply<32)sc-=7;
     if(supply>72)sc+=.8;
     if(sc>best.score)best={src,target,score:sc,supply};
   }
 }
 return best;
}

aiTry3230=function(f){
 if(paused3230||!started3230||f<=0||f>=FACTIONS3230.length)return;
 const t0=performance.now();
 let state=aiStrategicState3260[f];
 if(!state||campaignSeconds3230>=state.nextThink||state.objective<0||state.source<0){
   strategicThink3260(false);
   state=aiStrategicState3260[f];
 }
 if(!state)return;

 const rp=AI_ROLE_PROFILE3260[FACTIONS3230[f].role]||AI_ROLE_PROFILE3260.balanced;
 const reserve=state.reserveFloor||55;

 // Defensive factions can sit out an attack cycle while rebuilding the reserve.
 if(troops3230[f]<=reserve){
   state.stance=state.stance==='breakout'?state.stance:'defense';
   state.lastActionCampaign=campaignSeconds3230;
   return;
 }

 const cand=findExecutionCandidate3260(f,state);
 if(cand.target<0){
   state.nextThink=0;aiSnapshotDirty3260=true;return;
 }

 const def=owner6[cand.target];
 if(def===0&&!aiDeclarePlayerWar3260(f))return;

 // Supply discipline. Breakouts and emergency counterattacks may accept worse
 // logistics; ordinary offensives do not.
 const minSupply=(state.stance==='breakout'||state.stance==='defense')?20:
                 state.stance==='expansion'?25:34;
 if(def>=0&&cand.supply<minSupply){
   state.failures++;state.momentum=Math.max(0,state.momentum-1);
   state.nextThink=Math.min(state.nextThink,campaignSeconds3230+3);
   return;
 }

 // Real reserve: attack cost can never consume the protected strategic reserve.
 const tp=terrainProfile3250(cand.target),road=roadCross3230(cand.src,cand.target);
 let cost=(def<0?.75:1.75+(forts3212[cand.target]||0)*.42)*
          (1+Math.max(0,1-tp.move)*.20);
 if(road)cost*=.92;
 cost*=state.maneuver==='breakthrough'?1.10:state.maneuver==='pincer'?1.05:1;
 if(troops3230[f]-cost<reserve)return;

 troops3230[f]-=cost;
 state.actions++;state.lastActionCampaign=campaignSeconds3230;
 const p=aiAttackProbability3260(f,cand.src,cand.target,state);

 if(Math.random()<p){
   const oldOwner=def;
   owner6[cand.target]=f;forts3212[cand.target]=0;
   if(oldOwner>=0)troops3230[oldOwner]=Math.max(0,troops3230[oldOwner]-(1.25+state.momentum*.16));
   if(oldOwner>=0&&capitals[oldOwner]===cand.target)handleCapitalFall3230(oldOwner,cand.target,f);

   state.successes++;state.momentum=Math.min(4,state.momentum+1);
   if(cand.target===state.objective){
     state.source=cand.target;
     state.objective=state.secondary>=0?state.secondary:-1;
     state.secondary=-1;state.nextThink=campaignSeconds3230+2;
   }else state.source=cand.target;

   cacheDirty=true;supplyDirty3220=true;
   markEncirclementDirty3254();
   aiSnapshotDirty3260=true;
 }else{
   state.failures++;state.momentum=Math.max(0,state.momentum-1);
   // Repeated failed frontal attacks trigger a new route/manoeuvre choice.
   if(state.failures%3===0)state.nextThink=campaignSeconds3230+2;
 }

 aiExecMs3260=aiExecSamples3260?aiExecMs3260*.92+(performance.now()-t0)*.08:(performance.now()-t0);
 aiExecSamples3260++;
};


