function aiBestFortCell3260(f,state){
 const snap=aiSnapshot3260;if(!snap)return capitals[f];
 let best=capitals[f],score=-1e9;
 const samples=snap.frontier[f]||[];
 for(let i=0;i<samples.length;i+=Math.max(1,Math.floor(samples.length/65))){
   const c=samples[i];if(owner6[c]!==f||forts3212[c]>=3)continue;
   let sc=aiEnemyNeighbours3260(f,c)*2.0+(cities3212.has(c)?1.4:0)+(ports3212.has(c)?.8:0);
   sc+=100-aiLocalSupply3260(f,c)>.01?0:0;
   if(c===capitals[f])sc+=5;
   if(encircledMask3254?.[c])sc+=2.5;
   if(sc>score){score=sc;best=c}
 }
 return best;
}
function aiCoreBuildCell3260(f){
 const cap=capitals[f];
 if(cap>=0&&owner6[cap]===f)return cap;
 const snap=aiSnapshot3260,arr=snap?.frontier[f]||[];
 for(const c of arr)if(owner6[c]===f&&!encircledMask3254?.[c])return c;
 return -1;
}
function aiBuildRoadTowardCapital3260(f,state){
 if(botGold3230[f]<34||state.source<0||owner6[state.source]!==f)return false;
 const cap=capitals[f];if(cap<0||owner6[cap]!==f)return false;
 const L=loadLevel(MAX_GAME_LEVEL3233),src=state.source,s=L.offsets[src],e=L.offsets[src+1];
 let best=-1,bestD=angularHeuristic3254(src,cap);
 for(let k=s;k<e;k++){
   const n=L.edgeNbr[k];
   if(n<0||owner6[n]!==f||roadCross3230(src,n))continue;
   const d=angularHeuristic3254(n,cap);
   if(d<bestD){bestD=d;best=n}
 }
 if(best<0)return false;
 botGold3230[f]-=34;roads3212.push([src,best]);rebuildRoadEdges3212();
 supplyDirty3220=true;aiMarkDirty3260();return true;
}

botBuild3230=function(f){
 if(f<=0||f>=FACTIONS3230.length||!started3230)return;
 const state=aiStrategicState3260[f]||blankAIState3260(f);
 const rp=AI_ROLE_PROFILE3260[FACTIONS3230[f].role]||AI_ROLE_PROFILE3260.balanced;
 const gold=botGold3230[f];
 if(gold<45)return;

 // Keep strategic construction much rarer than tactical attacks.
 if(Math.random()>.24)return;

 if((state.stance==='defense'||state.stance==='breakout'||aiSnapshot3260?.capThreat[f]<13)&&gold>=50){
   const c=aiBestFortCell3260(f,state);
   if(c>=0&&owner6[c]===f&&forts3212[c]<3){
     botGold3230[f]-=50;forts3212[c]++;return;
   }
 }

 // Aggressive/growth factions build a corridor when the front is far from the
 // capital; this also gives their future route scoring a reason to reuse roads.
 if(gold>=90&&state.source>=0&&aiLocalSupply3260(f,state.source)<62&&Math.random()<.38){
   if(aiBuildRoadTowardCapital3260(f,state))return;
 }

 const core=aiCoreBuildCell3260(f);if(core<0)return;

 if(FACTIONS3230[f].role==='naval'&&gold>=70&&Math.random()<rp.naval*.28){
   const snap=aiSnapshot3260,front=snap?.frontier[f]||[];
   for(const c of front){
     if(owner6[c]===f&&isCoastal3212(c)&&!ports3212.has(c)){
       botGold3230[f]-=70;ports3212.add(c);supplyDirty3220=true;aiMarkDirty3260();return;
     }
   }
 }

 if(gold>=110&&Math.random()<.38*rp.industry){
   let c=core;
   const arr=aiSnapshot3260?.industries[f]||[];
   if(arr.length<3&&owner6[c]===f&&industryLevel3230[c]<3){
     botGold3230[f]-=110;industryLevel3230[c]++;industries3212.add(c);return;
   }
 }

 if(gold>=80&&Math.random()<.34){
   let c=core;
   if(owner6[c]===f&&cityLevel3230[c]<3){
     botGold3230[f]-=80;cityLevel3230[c]++;cities3212.add(c);aiMarkDirty3260();return;
   }
 }

 if(gold>=50){
   const c=aiBestFortCell3260(f,state);
   if(c>=0&&owner6[c]===f&&forts3212[c]<3){
     botGold3230[f]-=50;forts3212[c]++;
   }
 }
};


