// ================= /v3.26.0 =================



// ================= v3.26.1 · TERRITORIAL ECONOMY + SEA-ONLY FLEETS =================
//
// Economy:
// - territory, cities, industry, ports and roads have distinct output;
// - isolated territory has sharply reduced economic value;
// - supply/connectivity changes the output of structures;
// - capital and nationalism still matter;
// - armies, forts, infrastructure, fronts, fleets and prolonged wars cost money;
// - one shared cached snapshot avoids repeated 160k-cell scans.
//
// Fleets:
// - transport route is found through WATER CELLS ONLY;
// - if two coasts are not connected by sea, the transport cannot launch;
// - the visible ship and route stay on sea cells;
// - duration is based on the real maritime path, not a line through continents.


// -----------------------------------------------------------------------------
// 1. CACHED TERRITORIAL ECONOMY
// -----------------------------------------------------------------------------
const ECON_SNAPSHOT_PERIOD3261=3;
let economySnapshot3261=null;
let economyDirty3261=true;
let economyLastCampaign3261=-1e9;
let economyBuildMs3261=0;

function markEconomyDirty3261(){economyDirty3261=true}

function economyStructureSupply3261(f,cell){
 if(owner6[cell]!==f)return 0;
 if(f===0){
   const p=supplyPct3220(cell);
   return Math.max(.30,p/100);
 }
 return Math.max(.28,aiLocalSupply3260(f,cell)/100);
}

function rebuildEconomySnapshot3261(){
 const t0=performance.now(),F=FACTIONS3230.length,n=owner6.length;
 const territory=new Int32Array(F),isolated=new Int32Array(F),forts=new Int32Array(F);
 const roadSegments=new Int32Array(F);
 const cityLevels=new Float64Array(F),industryLevels=new Float64Array(F);
 const cityWeighted=new Float64Array(F),industryWeighted=new Float64Array(F);
 const portCount=new Int32Array(F),portWeighted=new Float64Array(F);

 // Single world scan for territory / isolation / forts.
 for(let i=0;i<n;i++){
   const f=owner6[i];
   if(f<0||f>=F)continue;
   territory[f]++;
   if(encircledMask3254?.[i])isolated[f]++;
   if(forts3212[i])forts[f]+=forts3212[i];
 }

 // Structures are sparse, so connectivity is evaluated only where it matters.
 for(const c of cities3212){
   const f=owner6[c];if(f<0||f>=F)continue;
   const lv=Math.max(1,cityLevel3230[c]||1),q=economyStructureSupply3261(f,c);
   cityLevels[f]+=lv;cityWeighted[f]+=lv*q;
 }
 for(const c of industries3212){
   const f=owner6[c];if(f<0||f>=F)continue;
   const lv=Math.max(1,industryLevel3230[c]||1),q=economyStructureSupply3261(f,c);
   industryLevels[f]+=lv;industryWeighted[f]+=lv*q;
 }
 for(const c of ports3212){
   const f=owner6[c];if(f<0||f>=F)continue;
   const q=economyStructureSupply3261(f,c);
   portCount[f]++;portWeighted[f]+=q;
 }

 // Count a road segment once, and only when both ends belong to the same state.
 for(const path of roads3212){
   for(let k=1;k<path.length;k++){
     const a=path[k-1],b=path[k],f=owner6[a];
     if(f>=0&&f<F&&owner6[b]===f)roadSegments[f]++;
   }
 }

 economySnapshot3261={
   territory,isolated,forts,roadSegments,
   cityLevels,industryLevels,cityWeighted,industryWeighted,portCount,portWeighted,
   campaign:campaignSeconds3230
 };
 economyDirty3261=false;
 economyLastCampaign3261=campaignSeconds3230;
 economyBuildMs3261=performance.now()-t0;
 return economySnapshot3261;
}

function ensureEconomySnapshot3261(force=false){
 if(force||!economySnapshot3261||economyDirty3261||
    campaignSeconds3230-economyLastCampaign3261>=ECON_SNAPSHOT_PERIOD3261)
   return rebuildEconomySnapshot3261();
 return economySnapshot3261;
}

function tradeIncome3261(f,snap){
 const ports=snap.portCount[f]||0;
 if(!ports)return 0;

 if(f===0){
   let v=0;
   for(let o=1;o<FACTIONS3230.length;o++){
     if(relations3220[o]!==1&&relations3220[o]!==3)continue;
     const ally=relations3220[o]===3?.18:0;
     const partnerPorts=snap.portCount[o]||0;
     const partnerIndustry=snap.industryWeighted[o]||0;
     v+=.20+Math.min(.75,(snap.territory[o]||0)*.0015)+
        Math.min(.55,partnerIndustry*.025)+
        Math.min(.28,partnerPorts*.045)+ally;
   }
   return v*Math.min(1.35,.70+ports*.09);
 }

 // AI factions get a small abstract external market. Naval personalities profit
 // more from having functional ports.
 const naval=FACTIONS3230[f]?.role==='naval'?1.24:1;
 return Math.min(1.55,ports*.105*naval+(snap.industryWeighted[f]||0)*.010);
}

function warCount3261(f){
 if(f===0){
   let n=0;for(let o=1;o<FACTIONS3230.length;o++)if(relations3220[o]===-1)n++;
   return n;
 }
 return relations3220[f]===-1?1:0;
}

function territorialEconomy3261(f){
 const snap=ensureEconomySnapshot3261();
 const territory=snap.territory[f]||0,isolated=snap.isolated[f]||0;
 const connectedTerritory=Math.max(0,territory-isolated*.72);
 const city=snap.cityWeighted[f]||0,industry=snap.industryWeighted[f]||0;
 const ports=snap.portWeighted[f]||0,roads=snap.roadSegments[f]||0;
 const fortLevels=snap.forts[f]||0;
 const trade=tradeIncome3261(f,snap);

 const policy=f===0?(research3230.levels.policy||0):0;
 const tech=f===0?(research3230.levels.technology||0):0;
 const med=f===0?(research3230.levels.medicine||0):0;

 const cap=capitalEconomyFactor3230(f);
 const nat=.82+Math.max(0,Math.min(100,nationalism3230[f]))*.003;

 const territoryIncome=.85+connectedTerritory*.00345*0.32077954;
 const cityIncome=city*.42;
 const industryIncome=industry*.76;
 const portIncome=ports*.34;
 const roadIncome=Math.min(1.75,roads*.0042*0.56637403);
 const knowledge=policy*.14+tech*.08;

 const grossBase=territoryIncome+cityIncome+industryIncome+portIncome+
                 roadIncome+trade+knowledge;
 const gross=grossBase*cap*nat;

 // Operating costs.
 const armyMaintenance=(troops3230[f]||0)*.00165;
 const fortMaintenance=fortLevels*.032*0.32077954;
 const cityMaintenance=(snap.cityLevels[f]||0)*.014;
 const industryMaintenance=(snap.industryLevels[f]||0)*.026;
 const portMaintenance=(snap.portCount[f]||0)*.032;
 const roadMaintenance=roads*.00075*0.56637403;

 const wars=warCount3261(f);
 const prolonged=Math.min(.32,campaignSeconds3230/1000*.09);
 const warMaintenance=wars*(.11+prolonged)+
   (f===0?activeFronts3230.length*.075:aiStrategicState3260[f]?.stance==='offensive'?.07:0);
 const fleetMaintenance=f===0
   ?fleets3212.filter(x=>x.f===0).length*.10
   :0;

 const maintenance=armyMaintenance+fortMaintenance+cityMaintenance+
   industryMaintenance+portMaintenance+roadMaintenance+warMaintenance+fleetMaintenance;

 const net=gross-maintenance;

 // Recruitment is mostly urban, with industry/logistics supporting its capacity.
 const isolationFactor=territory?Math.max(.48,1-isolated/territory*.72):1;
 const troopGross=(.34+connectedTerritory*.00085*0.32077954+city*.185+
   industry*.038+ports*.032+med*.095)*Math.max(.70,cap)*isolationFactor;

 const max=620+connectedTerritory*.48*0.32077954+(snap.cityLevels[f]||0)*145+
   (snap.industryLevels[f]||0)*42+med*55;

 return {
   gold:net, troop:troopGross, max,
   gross,maintenance,net,trade,
   territoryIncome:territoryIncome*cap*nat,
   cityIncome:cityIncome*cap*nat,
   industryIncome:industryIncome*cap*nat,
   portIncome:portIncome*cap*nat,
   roadIncome:roadIncome*cap*nat,
   territory,isolated,connectedTerritory,
   cityLevels:snap.cityLevels[f]||0,
   industryLevels:snap.industryLevels[f]||0,
   ports:snap.portCount[f]||0,
   roads,fortLevels,wars,
   connectivity:territory?Math.max(0,Math.min(100,Math.round(connectedTerritory/territory*100))):100
 };
}

