// 4. SEA-ONLY DRAWING / SHIP POSITION
// -----------------------------------------------------------------------------
function ensureFleetSeaRoute3261(f){
 if(f.seaRoute?.length){
   const L=loadLevel(MAX_GAME_LEVEL3233);
   let ok=true;for(const c of f.seaRoute)if(c<0||c>=L.n||L.land[c]>=0){ok=false;break}
   if(ok)return f.seaRoute;
 }
 const r=findSeaRoute3261(f.from,f.to);
 if(r?.length)f.seaRoute=r;
 return r;
}

function drawFleetsSea3261(R,cx,cy,now,C){
 if(!fleets3212.length)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 for(const f of fleets3212){
   const route=ensureFleetSeaRoute3261(f);
   if(!route||!route.length)continue;

   // Route: sea-cell centres only. No source->destination geodesic is drawn.
   ctx.beginPath();let started=false;
   for(const c of route){
     const j=c*3,p=projectVec(C[j]/32767,C[j+1]/32767,C[j+2]/32767,R,cx,cy);
     if(p[2]<.02){started=false;continue}
     if(!started){ctx.moveTo(p[0],p[1]);started=true}else ctx.lineTo(p[0],p[1]);
   }
   ctx.setLineDash([3,3]);ctx.strokeStyle='rgba(97,218,224,.42)';
   ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);

   const t=Math.max(0,Math.min(.9999,(now-f.start)*Math.max(1,gameSpeed3212)/Math.max(1,f.duration)));
   const pos=t*(route.length-1),i=Math.floor(pos),q=pos-i;
   const a=route[Math.min(i,route.length-1)],b=route[Math.min(i+1,route.length-1)];
   const ia=a*3,ib=b*3;
   let v;
   if(a===b)v=[C[ia]/32767,C[ia+1]/32767,C[ia+2]/32767];
   else{
     const av=[C[ia]/32767,C[ia+1]/32767,C[ia+2]/32767],
           bv=[C[ib]/32767,C[ib+1]/32767,C[ib+2]/32767];
     v=slerp3212(av,bv,q);
   }
   const p=projectVec(v[0],v[1],v[2],R,cx,cy);
   if(p[2]>.02){
     ctx.beginPath();ctx.arc(p[0],p[1],3.3,0,Math.PI*2);
     ctx.fillStyle='#7ce5e7';ctx.fill();
     ctx.strokeStyle='#061019';ctx.lineWidth=1;ctx.stroke();
   }
 }
 ctx.restore();
}

// Before resolving a fleet, verify once more that it owns a valid sea-only path.
// Geography is static, so this is effectively free after launch.
const _updateFleetsSeaBase3261=updateFleets3212;
updateFleets3212=function(now){
 if(fleets3212.length){
   const invalid=[];
   for(let i=0;i<fleets3212.length;i++){
     const f=fleets3212[i],route=ensureFleetSeaRoute3261(f);
     if(!route||!route.length)invalid.push(i);
   }
   for(let q=invalid.length-1;q>=0;q--){
     const i=invalid[q],f=fleets3212[i];
     if(f?.f===0)troops3230[0]+=Math.floor((f.troops||0)*.85);
     fleets3212.splice(i,1);
     if(f?.f===0)toast('Transporte cancelado: la ruta no es marítima');
   }
 }
 const before=fleets3212.length;
 _updateFleetsSeaBase3261(now);
 if(fleets3212.length!==before)markEconomyDirty3261();
};


