 if(!g||port<0||!ports3212.has(port)||owner6[port]===0){toast('Selecciona un puerto enemigo');return}
 const enemy=owner6[port];
 if(enemy>=0&&relations3220[enemy]===3){toast('No puedes bloquear un puerto aliado');return}
 if(enemy>=0&&relations3220[enemy]!==-1){
   if(!confirm('El bloqueo naval supone un acto de guerra. ¿Declarar la guerra?'))return;
   relations3220[enemy]=-1;updateFrontDock3220();aiMarkDirty3260();
 }
 const sea=bestPortSea3270(port,g.cell);
 if(sea<0||!setNavalDestination3270(g,sea)){toast('No existe ruta marítima hasta ese puerto');return}
 g.order='blockade';g.targetPort=port;g.targetSea=sea;g.escortFleetId=-1;
 toast('Flota enviada a bloquear '+landName3230(port));
