const _territorialEconomyNavalBase3270=territorialEconomy3261;
territorialEconomy3261=function(f){
 const base=_territorialEconomyNavalBase3270(f);
 const ratio=navalFactionBlockadeRatio3270(f);
 const navalMaintenance=navalGroups3270
   .filter(g=>g.f===f)
   .reduce((s,g)=>s+(.035+g.maxStrength*.0032),0);

 if(ratio<=0&&navalMaintenance<=0)return {...base,navalMaintenance,blockadeRatio:0};

 const tradeLoss=base.trade*ratio*.82;
 const portLoss=base.portIncome*ratio*.72;
 const extra=navalMaintenance;
 return {
   ...base,
   trade:Math.max(0,base.trade-tradeLoss),
   portIncome:Math.max(0,base.portIncome-portLoss),
   gross:Math.max(0,base.gross-tradeLoss-portLoss),
   maintenance:base.maintenance+extra,
   net:base.net-tradeLoss-portLoss-extra,
   troop:base.troop*(1-ratio*.16),
   navalMaintenance:extra,
   blockadeRatio:ratio
 };
};
economyRate3230=territorialEconomy3261;
income3212=function(){return economyRate3230(0).gold};
tradeIncome3230=function(){return territorialEconomy3261(0).trade};
tradeIncome3220=function(){return territorialEconomy3261(0).trade};

// Blockaded player ports cannot act as normal sea-supply relays.
activateSeaLinks3253=function(){
 const ownedPorts=[];
 for(const p of ports3212)if(owner6[p]===0&&navalPortBlockadeLevel3270(p)<.84)ownedPorts.push(p);
 if(ownedPorts.length<2)return 0;

 const origins=ownedPorts.filter(p=>{
   const c=supplyCost3253[p];
   return c!==SUPPLY_INF3253&&c<=78&&navalPortBlockadeLevel3270(p)<.60;
 });
 if(!origins.length)return 0;

 const tech=research3230.levels.technology||0;
 const seeds=[];let links=0;
 for(const dest of ownedPorts){
   const destBlock=navalPortBlockadeLevel3270(dest);
   if(destBlock>=.84)continue;
   let best=supplyCost3253[dest],bestOrigin=-1;
   for(const origin of origins){
     if(origin===dest)continue;
     const angle=angleBetweenCells3253(origin,dest);
     const blockCost=(navalPortBlockadeLevel3270(origin)+destBlock)*22;
     const seaCost=Math.max(8,Math.round((11+angle*14)*(1-tech*.035)+blockCost));
     const nc=supplyCost3253[origin]+seaCost;
     if(nc<best){best=nc;bestOrigin=origin}
   }
   if(bestOrigin>=0&&best<=SUPPLY_MAX_COST3253){
     if(supplyCost3253[dest]===SUPPLY_INF3253)supplyTouched3253.push(dest);
     supplyCost3253[dest]=best;
     supplyParent3253[dest]=-1;
     supplySourceCell3253[dest]=dest;
     supplySourceKind3253[dest]=3;
     supplyHops3253[dest]=0;
     supplyRoadHops3253[dest]=0;
     supplySeaOrigin3253[dest]=bestOrigin;
     seeds.push(dest);links++;
   }
 }
 propagateSupply3253(seeds);
 return links;
};


