// 3. TRANSPORTS: ESCORT / RISK / INTERCEPTION
// -----------------------------------------------------------------------------
launchSeaTransport3261=function(source,dest){
 if(source<0||owner6[source]!==0||!ports3212.has(source)){
   toast('El puerto de origen ya no está disponible');return false;
 }
 if(navalPortBlockadeLevel3270(source)>=.84){
   toast('El puerto está bajo bloqueo naval intenso');return false;
 }
 if(dest<0||!isCoastal3212(dest)||loadLevel(MAX_GAME_LEVEL3233).land[dest]<0){
   toast('El destino necesita costa');return false;
 }
 if(owner6[dest]===0){toast('La costa ya es tuya');return false}

 const amount=Math.floor(troops3230[0]*Number(strength3212.value)/100);
 if(amount<15||gold3212<55){
   toast('Necesitas 55 oro y al menos 15 tropas');return false;
 }

 const seaRoute=findSeaRoute3261(source,dest);
 if(!seaRoute?.length){toast('No existe una ruta marítima continua hasta esa costa');return false}

 const risk=navalRouteRisk3270(0,seaRoute);
 if(risk.risk>8){
   if(!confirm(`La ruta atraviesa una zona con superioridad naval enemiga (${Math.round(risk.risk)}). ¿Enviar el convoy igualmente?`))
     return false;
 }

 const enemy=owner6[dest];
 if(enemy>=0&&relations3220[enemy]===3){
   toast('Es un aliado · rompe la alianza antes de desembarcar');return false;
 }
 if(enemy>=0&&relations3220[enemy]>=2){
   if(!confirm('Hay un pacto vigente con '+factionName3230(enemy)+'. ¿Romperlo y lanzar el desembarco?'))return false;
   relations3220[enemy]=-1;
 }else if(enemy>=0&&relations3220[enemy]!==-1)relations3220[enemy]=-1;

 const travel=fleetTravelMs3261(seaRoute);
 gold3212-=55;troops3230[0]-=amount;
 const tr={
   id3270:nextTransportId3270++,from:source,to:dest,f:0,start:performance.now(),
   duration:travel,troops:amount,done:false,seaRoute,_lastIntercept3270:-1e9
 };
 fleets3212.push(tr);
 const escort=assignEscortForTransport3270(tr);
 markEconomyDirty3261();
 toast(`Convoy marítimo · ${amount} tropas · ${seaRoute.length} hex.${escort?' · escoltado':''}`);
 updateFrontDock3220(true);updateUI3230();saveGame3212();needsRender=true;
 return true;
};

function launchAISeaTransport3270(f,source,dest,amount){
 if(source<0||dest<0||owner6[source]!==f||!ports3212.has(source)||owner6[dest]===f)return false;
 if(botGold3230[f]<55||troops3230[f]-amount<(aiStrategicState3260[f]?.reserveFloor||50))return false;
 const seaRoute=findSeaRoute3261(source,dest);if(!seaRoute?.length)return false;

 const risk=navalRouteRisk3270(f,seaRoute);
 const role=FACTIONS3230[f]?.role;
 if(risk.risk>(role==='naval'?15:9))return false;

 botGold3230[f]-=55;troops3230[f]-=amount;
 const tr={
   id3270:nextTransportId3270++,from:source,to:dest,f,start:performance.now(),
   duration:fleetTravelMs3261(seaRoute),troops:amount,done:false,seaRoute,_lastIntercept3270:-1e9
 };
 fleets3212.push(tr);
 assignEscortForTransport3270(tr);
 markEconomyDirty3261();return true;
}


