// 4. AI NAVAL STRATEGY
// -----------------------------------------------------------------------------
function randomOwnedPort3270(f){
 const arr=[];for(const p of ports3212)if(owner6[p]===f)arr.push(p);
 return arr.length?arr[(Math.random()*arr.length)|0]:-1;
}
function nearestHostilePort3270(f,fromPort){
 const startSea=bestPortSea3270(fromPort),candidates=[];
 for(const p of ports3212){
   const o=owner6[p];
   if(o<0||o===f||!navalHostile3270(f,o))continue;
   candidates.push(p);
 }
 if(!candidates.length)return -1;
 let best=-1,bestD=1e9;
 for(const p of candidates){
   const s=bestPortSea3270(p,startSea);if(s<0)continue;
   const d=angularHeuristic3254(startSea,s);
   if(d<bestD){bestD=d;best=p}
 }
 return best;
}

function aiBuildNavalForces3270(f){
 const role=FACTIONS3230[f]?.role;
 const ports=[];for(const p of ports3212)if(owner6[p]===f)ports.push(p);
 if(!ports.length)return;
 const existing=factionNavalGroups3270(f).length;
 const desired=Math.min(role==='naval'?6:role==='aggressive'?4:3,1+Math.ceil(ports.length/2));
 if(existing>=desired||botGold3230[f]<NAVAL_BUILD_COST3270+85)return;
 const port=ports[(f+existing)%ports.length];
 buildNavalGroup3270(f,port,false);
}

function aiNavalPlan3270(f){
 if(campaignSeconds3230<navalAiNextPlan3270[f])return;
 navalAiNextPlan3270[f]=campaignSeconds3230+8+(f%4);
 aiBuildNavalForces3270(f);

 const groups=factionNavalGroups3270(f);if(!groups.length)return;
 const role=FACTIONS3230[f]?.role;

 // A blockaded home port has priority.
 let threatened=-1,threat=.15;
 for(const p of ports3212)if(owner6[p]===f){
   const lv=navalPortBlockadeLevel3270(p);
   if(lv>threat){threat=lv;threatened=p}
 }

 for(const g of groups){
   if(threatened>=0){
     g.home=threatened;g.order='patrol';g.targetPort=-1;
     setNavalDestination3270(g,bestPortSea3270(threatened,g.cell));
     continue;
   }

   if(g.strength<g.maxStrength*.38){g.order='return';continue}

   const enemyPort=nearestHostilePort3270(f,g.home);
   if(enemyPort>=0&&(role==='naval'||role==='aggressive'||Math.random()<.42)){
     g.order='blockade';g.targetPort=enemyPort;
     setNavalDestination3270(g,bestPortSea3270(enemyPort,g.cell));
   }else{
     g.order='intercept';g.targetPort=-1;
   }
 }

 // Periodic AI amphibious landing from a protected port.
 if(campaignSeconds3230<navalAiNextLanding3270[f])return;
 navalAiNextLanding3270[f]=campaignSeconds3230+(role==='naval'?18:26)+f;

 const source=randomOwnedPort3270(f);if(source<0)return;
 const target=nearestHostilePort3270(f,source);if(target<0)return;
 const reserve=aiStrategicState3260[f]?.reserveFloor||55;
 const available=Math.floor(troops3230[f]-reserve);
 if(available<24)return;
 const amount=Math.max(18,Math.min(75,Math.floor(available*(role==='naval'?.26:.18))));
 launchAISeaTransport3270(f,source,target,amount);
}


