function navalTick3270(){
 if(!started3230||paused3230||gameSpeed3212<=0)return;
 const t0=performance.now();

 for(const tr of fleets3212)if(!tr.id3270)tr.id3270=nextTransportId3270++;

 for(let f=1;f<FACTIONS3230.length;f++)aiNavalPlan3270(f);

 for(const g of navalGroups3270){
   updateNavalOrder3270(g,campaignSeconds3230);
   navalAdvanceGroup3270(g);

   // AI repairs automatically at its home port.
   if(g.f>0&&navalGroupAtHome3270(g)&&g.strength<g.maxStrength&&botGold3230[g.f]>20){
     const heal=Math.min(g.maxStrength-g.strength,.65*Math.max(1,gameSpeed3212));
     const cost=heal*2.4;
     if(botGold3230[g.f]>=cost){botGold3230[g.f]-=cost;g.strength+=heal}
   }
 }

 navalBattleTick3270();
 interceptTransports3270();
 rebuildNavalBlockades3270();

 navalTickMs3270=performance.now()-t0;
 updateMini3220();
 if(sysTab3220==='naval'&&document.getElementById('systemsPanel3213')?.classList.contains('open'))
   renderSystems3220();
 needsRender=true;
}


