// Full planner replacement: same cheap frontier execution, but a long-range goal
// gives it direction over several successive conquests.
aiPlanFaction3260=function(f,snap){
 const fac=FACTIONS3230[f],rp=AI_ROLE_PROFILE3260[fac.role]||AI_ROLE_PROFILE3260.balanced;
 const old=aiStrategicState3260[f]||blankAIState3260(f);
 const econ=territorialEconomy3261(f);
 const max=Math.max(1,econ.max);
 const reserveFloor=dynamicReserve3271(f,snap,rp);
 const troops=troops3230[f],ratio=troops/max;
 const ownPocket=snap.encCount[f]>0,capThreat=snap.capThreat[f];
 const historic=aiHistoricRecoveryTarget3260(f,snap);
 const atWarPlayer=relations3220[f]===-1&&snap.playerBorder[f]>0;

 let stance='offensive',reason='presión organizada sobre el frente';

 if(ownPocket){
   stance='breakout';reason='romper el cerco propio';
 }else if(capThreat<13){
   stance='defense';reason='proteger la capital amenazada';
 }else if(troops<reserveFloor*1.03){
   stance='defense';reason='reconstituir la reserva';
 }else if(econ.net<0&&ratio<.72){
   stance='defense';reason='recuperar economía y reservas';
 }else if(historic>=0){
   stance='recovery';reason='recuperar la capital histórica';
 }else if(snap.neutralBorder[f]>Math.max(3,snap.hostileBorder[f]*.52)&&
         (fac.role==='growth'||ratio<.60)){
   stance='expansion';reason='expandirse sin abrir una guerra costosa';
 }else if(atWarPlayer&&fac.role==='defense'){
   stance='containment';reason='contener la ofensiva del jugador';
 }else if(atWarPlayer){
   stance=ratio>.50?'offensive':'defense';
   reason=stance==='offensive'?'presionar al jugador':'estabilizar el frente contra el jugador';
 }else if(ratio>.74&&capThreat>22){
   stance='offensive';reason='explotar superioridad de reservas';
 }else if(fac.role==='growth'){
   stance='expansion';reason='crecimiento territorial';
 }else if(fac.role==='defense'){
   stance='defense';reason='consolidar posiciones';
 }

 const goal=chooseStrategicGoal3271(f,snap,stance);
 let forcedOwner=null,objHint=goal.cell;

 if(stance==='recovery')objHint=historic;
 if(stance==='containment'||(stance==='offensive'&&atWarPlayer))forcedOwner=0;
 if(stance==='expansion')objHint=-1;

 let cand;
 if(stance==='breakout'&&snap.encircled[f].length){
   const L=loadLevel(MAX_GAME_LEVEL3233);
   let best={src:-1,target:-1,score:-1e9};
   for(const src of snap.encircled[f]){
     if(owner6[src]!==f)continue;
     const s=L.offsets[src],e=L.offsets[src+1];
     for(let k=s;k<e;k++){
       const t=L.edgeNbr[k];
       if(t<0||L.land[t]<0||!aiTargetAllowed3260(f,t))continue;
       let sc=aiStrategicValue3260(f,src,t,stance,'breakout',-1);
       const ts=L.offsets[t],te=L.offsets[t+1];let relief=0;
       for(let q=ts;q<te;q++){
         const n=L.edgeNbr[q];
         if(n>=0&&owner6[n]===f&&!encircledMask3254?.[n])relief++;
       }
       sc+=relief*4.5;
       if(sc>best.score)best={src,target:t,score:sc};
     }
   }
   cand=best;
 }else{
   cand=findBestAICandidate3260(f,snap,stance,objHint,forcedOwner);
   if(cand.target<0)cand=findBestAICandidate3260(f,snap,stance,objHint,null);
 }

 const maneuver=chooseAIManeuver3260(f,cand.src,cand.target,stance);
 const supply=cand.src>=0?aiLocalSupply3260(f,cand.src):0;
 const state={
   faction:f,serial:aiPlanSerial3260++,stance,maneuver,
   objective:cand.target,objectiveOwner:cand.target>=0?owner6[cand.target]:-2,
   strategicGoal:goal.cell,strategicGoalType:goal.type,
   source:cand.src,secondary:-1,score:cand.score||0,reserveFloor,supply,
   targetEnemy:cand.target>=0?owner6[cand.target]:-1,
   reason,nextThink:campaignSeconds3230+AI_STRATEGIC_CAMPAIGN_PERIOD3260+
     ((f*2+aiPlanSerial3260)%4),
   momentum:Math.max(0,Math.min(4,old.momentum||0)),
   successes:old.successes||0,failures:old.failures||0,actions:old.actions||0,
   lastActionCampaign:old.lastActionCampaign||-1e9
 };

 if(maneuver==='pincer'&&cand.target>=0){
   const L=loadLevel(MAX_GAME_LEVEL3233),s=L.offsets[cand.target],e=L.offsets[cand.target+1];
   let second=-1,secondSc=-1e9;
   for(let k=s;k<e;k++){
     const t=L.edgeNbr[k];
     if(t<0||owner6[t]===f||!aiTargetAllowed3260(f,t))continue;
     const sc=aiStrategicValue3260(f,cand.src,t,stance,'pincer',goal.cell);
     if(sc>secondSc){secondSc=sc;second=t}
   }
   state.secondary=second;
 }

 aiStrategicState3260[f]=state;
 return state;
};


// Learn from the result of each tactical execution without adding another search.
