botBuild3230=function(f){
 if(f<=0||f>=FACTIONS3230.length||!started3230)return;
 if(campaignSeconds3230<aiBuildNext3271[f])return;
 aiBuildNext3271[f]=campaignSeconds3230+5+(f%4)*.8;

 const state=aiStrategicState3260[f]||blankAIState3260(f);
 const role=FACTIONS3230[f]?.role||'balanced';
 const econ=territorialEconomy3261(f);
 const need=aiEconomicNeed3271(f);
 const gold=botGold3230[f];
 if(gold<34)return;

 // 1) Immediate military emergency.
 if((state.stance==='defense'||state.stance==='breakout'||(aiSnapshot3260?.capThreat[f]??99)<14)&&gold>=50){
   const c=aiBestFortCell3260(f,state);
   if(c>=0&&owner6[c]===f&&forts3212[c]<3){
     botGold3230[f]-=50;forts3212[c]++;markEconomyDirty3261();return;
   }
 }

 // 2) Poor front supply: build a connector before more decorative structures.
 if(state.source>=0&&aiLocalSupply3260(f,state.source)<58&&gold>=70){
   if(aiBuildRoadTowardCapital3260(f,state)){markEconomyDirty3261();return}
 }

 const core=aiSafeCoreCell3271(f);
 if(core<0)return;

 // 3) Negative or weak economy: industry first.
 if((econ.net<.25||need.industryDensity<.34)&&gold>=110&&industryLevel3230[core]<3){
   botGold3230[f]-=110;industryLevel3230[core]++;industries3212.add(core);
   markEconomyDirty3261();aiMarkDirty3260();return;
 }

 // 4) Population / recruitment base.
 if((need.cityDensity<.38||econ.troop<1.1)&&gold>=80&&cityLevel3230[core]<3){
   botGold3230[f]-=80;cityLevel3230[core]++;cities3212.add(core);
   markEconomyDirty3261();aiMarkDirty3260();return;
 }

 // 5) Naval states ensure they have functional ports before adding more fleets.
 if(role==='naval'&&need.ports<2&&gold>=70){
   const arr=aiSnapshot3260?.frontier[f]||[];
   for(const c of arr){
     if(owner6[c]===f&&isCoastal3212(c)&&!ports3212.has(c)){
       botGold3230[f]-=70;ports3212.add(c);
       markEconomyDirty3261();supplyDirty3220=true;aiMarkDirty3260();return;
     }
   }
 }

 // 6) Balanced development when healthy.
 if(gold>=140&&industryLevel3230[core]<3&&(role==='growth'||Math.random()<.58)){
   botGold3230[f]-=110;industryLevel3230[core]++;industries3212.add(core);
   markEconomyDirty3261();aiMarkDirty3260();return;
 }
 if(gold>=105&&cityLevel3230[core]<3){
   botGold3230[f]-=80;cityLevel3230[core]++;cities3212.add(core);
   markEconomyDirty3261();aiMarkDirty3260();return;
 }

 if(gold>=50){
   const c=aiBestFortCell3260(f,state);
   if(c>=0&&owner6[c]===f&&forts3212[c]<3){
     botGold3230[f]-=50;forts3212[c]++;markEconomyDirty3261();
   }
 }
};


