async function downloadBlob3275(blob,name){
 // Native picker is the most reliable route on Chromium desktop when allowed.
 if(typeof window.showSaveFilePicker==='function'&&window.isSecureContext){
   try{
     const handle=await window.showSaveFilePicker({
       suggestedName:name,
       types:[{
         description:'Partida HEXATEGOS',
         accept:{'application/json':['.hexategos']}
       }]
     });
     const writable=await handle.createWritable();
     await writable.write(blob);
     await writable.close();
     return 'picker';
   }catch(e){
     if(e?.name==='AbortError')throw e;
     // Fall through: browser may expose the API but deny it in this context.
   }
 }

 const url=URL.createObjectURL(blob);
 try{
   const a=document.createElement('a');
   a.href=url;a.download=name;a.rel='noopener';
   a.style.display='none';
   document.body.appendChild(a);
   a.click();
   a.remove();
   return 'download';
 }finally{
   setTimeout(()=>URL.revokeObjectURL(url),5000);
 }
}

