 if(!force&&
    campaignSeconds3230-aiNationalLastCampaign3275<NATIONAL_PLAN_PERIOD3275&&
    wall-aiNationalLastWall3275<NATIONAL_WALL_MIN3275)return;

 rebuildNationalSamples3275();
