function upgradeNationalCity3275(f,p){
 let best=-1,bestScore=-1e9;
 for(const c of cities3212){
   if(owner6[c]!==f||encircledMask3254?.[c])continue;
   const lv=cityLevel3230[c]||1;if(lv>=3)continue;
   const sc=aiLocalSupply3260(f,c)+aiRoadDegree3260(c)*8+(industryLevel3230[c]||0)*10;
   if(sc>bestScore){bestScore=sc;best=c}
 }
 if(best<0)return false;
 const lv=cityLevel3230[best]||1,cost=60+lv*30;
 if(botGold3230[f]-cost<p.cashReserve)return false;
 cityLevel3230[best]=lv+1;cities3212.add(best);spend3275(f,'city',cost);
 return true;
}

function nationalDefense3275(f,p){
 const st=aiStrategicState3260[f]||blankAIState3260(f);
 const c=aiBestFortCell3260(f,st);
 if(c<0||owner6[c]!==f||forts3212[c]>=3)return false;
 const cost=50+(forts3212[c]||0)*20;
 if(botGold3230[f]-cost<p.cashReserve)return false;
 forts3212[c]++;spend3275(f,'defense',cost);return true;
}

function nationalNaval3275(f,p){
 const port=[...ports3212].find(c=>owner6[c]===f);
 if(port==null)return false;
 if(botGold3230[f]-NAVAL_BUILD_COST3270<p.cashReserve)return false;
 const before=botGold3230[f];
 if(!buildNavalGroup3270(f,port,false))return false;
 const cost=Math.max(0,before-botGold3230[f]);
 const s=aiNationalSpent3275[f];s.naval+=cost;s.total+=cost;p.built++;
 markEconomyDirty3261();return true;
}

// This replaces the older one-core build routine.
botBuild3230=function(f){
 if(f<=0||f>=FACTIONS3230.length||!started3230)return;
 ensureNationalPlans3275(false);

 let p=aiNationalPlan3275[f];
 if(!p)p=chooseNationalPolicy3275(f);

 if(campaignSeconds3230<aiBuildNext3271[f])return;
 // National building remains slow; each nation performs one investment at a time.
 aiBuildNext3271[f]=campaignSeconds3230+3.2+(f%4)*.65;

 const econ=territorialEconomy3261(f);
 const gold=botGold3230[f];
 if(gold<45)return;

 // Emergency overrides national budget.
 if((aiSnapshot3260?.capThreat[f]??99)<12||aiSnapshot3260?.encCount[f]>0){
   if(nationalDefense3275(f,p))return;
 }
 if(econ.net<-.35){
   if(buildNationalIndustry3275(f,p))return;
 }

 const snap=ensureEconomySnapshot3261();
 const cityCount=[...cities3212].reduce((n,c)=>n+(owner6[c]===f?1:0),0);
 const indCount=[...industries3212].reduce((n,c)=>n+(owner6[c]===f?1:0),0);
 const portCount=snap.portCount[f]||0;

 // Compute the categories most behind their national budget.
 const cats=['industry','road','city','port','defense','naval'];
 cats.sort((a,b)=>budgetNeed3275(f,b)-budgetNeed3275(f,a));

 for(const cat of cats){
   if(cat==='city'){
     if(cityCount<p.targetCities&&buildNationalCity3275(f,p))return;
     if(upgradeNationalCity3275(f,p))return;
   }else if(cat==='industry'){
     if(indCount<p.targetIndustry&&buildNationalIndustry3275(f,p))return;
     if(buildNationalIndustry3275(f,p))return;
   }else if(cat==='road'){
     if(buildNationalRoad3275(f,p))return;
   }else if(cat==='port'){
     if(portCount<p.targetPorts&&buildNationalPort3275(f,p))return;
   }else if(cat==='defense'){
     if(nationalDefense3275(f,p))return;
   }else if(cat==='naval'){
     if((FACTIONS3230[f]?.role==='naval'||p.policy==='maritime')&&nationalNaval3275(f,p))return;
   }
 }
};


