// ================= v3.27.6 · STABILIZATION / LONG-RUN AI AUDIT =================
//
// Fixes from the audit:
// - file export asks for the destination BEFORE serializing the 160k-cell state,
//   preserving browser user activation for the native file picker;
// - direct top-bar save button;
// - portable save still falls back to a normal Blob download;
// - old economic `gold` rate is unified with the true NET balance;
// - autosave is no longer attempted every ~7 campaign seconds;
// - strong naval blockade now counts for land encirclement;
// - blockade changes invalidate encirclement;
// - neutral/custom city labels no longer abort all later labels;
// - AI logistics uses one shared, cached, road-aware multi-faction supply field;
// - naval AI order priorities no longer overwrite the strategic port objective.
//
// Long-run balance:
// - passive snapshots every ~20 campaign seconds;
// - detects deficit, economic stagnation, weak road development and isolation;
// - national policy can self-correct from those trends;
// - optional 180 campaign-second accelerated audit runs on the REAL simulation,
//   then restores the original campaign byte-for-byte from an in-memory snapshot.


// ============================================================================
// 1. ROBUST SAVE: PICK DESTINATION FIRST, THEN SERIALIZE
// ============================================================================
function buildPortableFile3276(){
 const file=buildPortableFile3275();
 file.gameVersion='3.27.6';
 file.schema=OPENFRONT_FILE_SCHEMA3275;
 return file;
}

exportGameFile3273=async function(){
 if(!started3230){
   toast('Empieza o carga una partida antes de guardarla');
   return false;
 }

 let handle=null;
 const name=portableFilename3273();

 try{
   // IMPORTANT: invoke the picker immediately while the click still has
   // transient user activation. The previous implementation serialized first.
   if(typeof window.showSaveFilePicker==='function'&&window.isSecureContext){
     try{
       handle=await window.showSaveFilePicker({
         suggestedName:name,
         types:[{
           description:'Partida HEXATEGOS',
           accept:{'application/json':['.hexategos']}
         }]
       });
     }catch(e){
       if(e?.name==='AbortError'){
         portableStatus3275='Guardado cancelado.';
         return false;
       }
       handle=null; // browser exposes it but this context denies it -> fallback
     }
   }

   portableStatus3275='Preparando la partida actual…';
   if(sysTab3220==='settings')renderSystems3220();

   const file=buildPortableFile3276();
   const text=JSON.stringify(file);
   const blob=new Blob([text],{type:'application/json;charset=utf-8'});

   let method='download';
   if(handle){
     const writable=await handle.createWritable();
     await writable.write(blob);
     await writable.close();
     method='selector de archivos';
   }else{
     const url=URL.createObjectURL(blob);
     try{
       const a=document.createElement('a');
       a.href=url;a.download=name;a.rel='noopener';a.style.display='none';
       document.body.appendChild(a);a.click();a.remove();
     }finally{
       setTimeout(()=>URL.revokeObjectURL(url),6000);
     }
     method='descarga del navegador';
   }

   portableLastBytes3275=blob.size;
   portableStatus3275=`Guardada · ${(blob.size/1024/1024).toFixed(1)} MB · ${method}`;
   lastPortableSave3273={name,bytes:blob.size,campaign:campaignSeconds3230,at:Date.now()};
   toast(`Partida guardada · ${(blob.size/1024/1024).toFixed(1)} MB`);
   if(sysTab3220==='settings')renderSystems3220();
   return true;
 }catch(e){
   console.error(e);
   portableStatus3275='Error: '+(e?.message||'no se pudo generar el archivo');
   alert('No se pudo guardar la partida.\n\n'+portableStatus3275);
   if(sysTab3220==='settings')renderSystems3220();
   return false;
 }
};

