function aiSupplyLoss3276(a,b){
 const tk=terrainKey3250(b);
 let loss=4;
 if(roadCross3230(a,b))loss=1;
 else{
   if(tk==='mountain')loss+=2;
   else if(tk==='highmountain')loss+=4;
   else if(tk==='desert'||tk==='rainforest'||tk==='tundra')loss+=2;
   else if(tk==='forest'||tk==='steppe')loss+=1;
   if(riverCross3230(a,b))loss+=2;
 }
 return Math.max(1,Math.min(9,Math.round(loss*0.56637403)));
}

function rebuildAISupply3276(){
 const t0=performance.now(),L=loadLevel(MAX_GAME_LEVEL3233),n=L.n;
 if(!aiSupplyScore3276||aiSupplyScore3276.length!==n)aiSupplyScore3276=new Uint8Array(n);
 else aiSupplyScore3276.fill(0);

 const buckets=Array.from({length:101},()=>[]);
 let reached=0;

 // Capital = 100. Operational unblocked port = 88.
 for(let f=1;f<FACTIONS3230.length;f++){
   const cap=capitals[f];
   if(cap>=0&&owner6[cap]===f){
     aiSupplyScore3276[cap]=100;buckets[100].push(cap);
   }
 }
 for(const p of ports3212){
   const f=owner6[p];
   if(f<=0||navalPortBlockadeLevel3270(p)>=.78)continue;
   if(aiSupplyScore3276[p]<88){
     aiSupplyScore3276[p]=88;buckets[88].push(p);
   }
 }

 for(let score=100;score>0;score--){
   const bucket=buckets[score];
   while(bucket.length){
     const u=bucket.pop();
     if(aiSupplyScore3276[u]!==score)continue;
     reached++;
     const f=owner6[u],s=L.offsets[u],e=L.offsets[u+1];
     for(let k=s;k<e;k++){
       const v=L.edgeNbr[k];
       if(v<0||owner6[v]!==f||f<=0)continue;
       let ns=score-aiSupplyLoss3276(u,v);
       if(encircledMask3254?.[v])ns-=8;
       if(ns<=0||ns<=aiSupplyScore3276[v])continue;
       aiSupplyScore3276[v]=ns;
       buckets[ns].push(v);
     }
   }
 }

 aiSupplyReached3276=reached;
 aiSupplyBuildMs3276=performance.now()-t0;
 aiSupplyDirty3276=false;
 aiSupplyLastWall3276=performance.now();
 return aiSupplyScore3276;
}

