aiNavalPlan3270=function(f){
 if(campaignSeconds3230<navalAiNextPlan3270[f])return;
 navalAiNextPlan3270[f]=campaignSeconds3230+8+(f%4);
 aiBuildNavalForces3270(f);

 const groups=factionNavalGroups3270(f);
 if(!groups.length)return;
 const role=FACTIONS3230[f]?.role;
 const goal=aiGoal3271[f];

 // Priority 1: a threatened own port.
 let threatened=-1,threat=.15;
 for(const p of ports3212)if(owner6[p]===f){
   const lv=navalPortBlockadeLevel3270(p);
   if(lv>threat){threat=lv;threatened=p}
 }

 // Priority 2: transports need escorts.
 const friendlyTransports=fleets3212.filter(x=>(x.f??0)===f);

 for(let gi=0;gi<groups.length;gi++){
   const g=groups[gi];

   if(g.strength<g.maxStrength*.34){
     g.order='return';g.targetPort=-1;continue;
   }

   if(threatened>=0){
     g.home=threatened;g.order='patrol';g.targetPort=-1;
     const sea=bestPortSea3270(threatened,g.cell);
     if(sea>=0)setNavalDestination3270(g,sea);
     continue;
   }

   if(friendlyTransports.length&&gi===0){
     const tr=friendlyTransports[0];
     if(!tr.id3270)tr.id3270=nextTransportId3270++;
     g.order='escort';g.escortFleetId=tr.id3270;g.targetPort=-1;
     continue;
   }

   // Priority 3: the land strategic goal is an enemy port.
   if(goal?.cell>=0&&goal.type==='port'&&ports3212.has(goal.cell)&&
      owner6[goal.cell]!==f&&navalHostile3270(f,owner6[goal.cell])){
     g.order='blockade';g.targetPort=goal.cell;g.escortFleetId=-1;
     const sea=bestPortSea3270(goal.cell,g.cell);
     if(sea>=0)setNavalDestination3270(g,sea);
     continue;
   }

   // Priority 4: opportunistic blockade / interception.
   const enemyPort=nearestHostilePort3270(f,g.home);
   if(enemyPort>=0&&(role==='naval'||role==='aggressive'||gi===1)){
     g.order='blockade';g.targetPort=enemyPort;g.escortFleetId=-1;
     const sea=bestPortSea3270(enemyPort,g.cell);
     if(sea>=0)setNavalDestination3270(g,sea);
   }else{
     g.order='intercept';g.targetPort=-1;g.escortFleetId=-1;
   }
 }

 // Amphibious operations remain subordinate to reserve and sea-risk checks.
 if(campaignSeconds3230<navalAiNextLanding3270[f])return;
 navalAiNextLanding3270[f]=campaignSeconds3230+(role==='naval'?20:29)+f;
 const source=randomOwnedPort3270(f);
 if(source<0||navalPortBlockadeLevel3270(source)>=.72)return;
 const target=nearestHostilePort3270(f,source);
 if(target<0)return;
 const reserve=aiStrategicState3260[f]?.reserveFloor||55;
 const available=Math.floor(troops3230[f]-reserve);
 if(available<28)return;
 const amount=Math.max(20,Math.min(72,Math.floor(available*(role==='naval'?.24:.16))));
 launchAISeaTransport3270(f,source,target,amount);
};


