function auditDiffReport3276(before,after){
 const out=[];
 for(let f=1;f<FACTIONS3230.length;f++){
   const a=before[f],b=after[f],w=[];
   if(b.net<0)w.push('déficit');
   if(b.cities<=a.cities&&b.industries<=a.industries&&b.roads<=a.roads)w.push('sin desarrollo');
   if(b.territory>80&&b.roads<Math.sqrt(b.territory)*1.15)w.push('pocas carreteras');
   if(b.territory&&b.isolated/b.territory>.18)w.push('aislamiento');
   out.push({
     f,
     territory:b.territory-a.territory,
     cities:b.cities-a.cities,
     industries:b.industries-a.industries,
     roads:b.roads-a.roads,
     ports:b.ports-a.ports,
     gold:b.gold-a.gold,
     net:b.net,
     warnings:w
   });
 }
 return out;
}

