function runAIFrontScenarioTests3280(){
 const tests=[];
 const push=(name,ok,detail)=>tests.push({name,ok:!!ok,detail});
 // A: two similar countries -> a coherent single campaign allocation.
 const aTotal=300,aReserve=aTotal*.20,aFront=Math.min(aTotal*.28,aTotal-aReserve);
 push('A · frontera equilibrada',aFront>50&&aFront+aReserve<=aTotal,`frente ${aFront.toFixed(0)} / reserva ${aReserve.toFixed(0)}`);
 // B: strong vs weak -> capital objective receives campaign priority.
 const capScore=26+3*5,normalScore=2*5;
 push('B · fuerte contra débil',capScore>normalScore*2,'capital prioritaria');
 // C: two enemies -> allocations cannot duplicate troops.
 const cTotal=500,cReserve=120,cF1=145,cF2=110,cGarrison=90;
 push('C · dos enemigos',cF1+cF2+cGarrison+cReserve<=cTotal,`comprometido ${cF1+cF2+cGarrison+cReserve}/${cTotal}`);
 // D: capital threat -> reserve target rises and defensive slot may expand.
 const normalR=.21,threatR=Math.min(.36,normalR+.08);
 push('D · capital amenazada',threatR>normalR&&threatR>=.25,`reserva ${(threatR*100).toFixed(0)}%`);
 // E: stalled campaign -> reevaluation triggers after repeated failures/time.
 const stalled=(4>=4)||(25>20);
 push('E · frente bloqueado',stalled,'cambio de eje/defensa habilitado');
 // F: live invariants are the long-war guard. The accelerated audit exercises it.
 const live=aiLongWarErrors3280.length?aiLongWarErrors3280:validateAICampaigns3280();
 push('F · guerra larga / invariantes',live.length===0,live.length?live.join('; '):(aiLongWarErrors3280.length?'auditoría larga correcta':'sin duplicados/negativos en estado actual'));
 aiFrontTests3280=tests;return tests;
}
