const REGIONAL_POLICY_NAMES3284={admin:'CAPITAL Y SERVICIOS',urban:'DESARROLLO URBANO',industrial:'POLO INDUSTRIAL',commercial:'COMERCIO Y PUERTOS',logistics:'LOGÍSTICA MILITAR',defense:'REGIÓN DEFENSIVA'};
const REGIONAL_TASK_NAMES3284={city:'Ciudad regional',industry:'Industria',road:'Corredor viario',port:'Puerto'};
const REGIONAL_PLANNING_SECONDS3284=22;
