   const city=nearby.filter(x=>cities3212.has(x)).length;
   const industry=nearby.filter(x=>industries3212.has(x)).length;
   const port=nearby.filter(x=>ports3212.has(x)).length;
   const front=fronts.find(fr=>regionalSaneCell3284(f,fr.stagingArea)&&angularHeuristic3254(c,fr.stagingArea)<10);
   const supply=aiLocalSupply3260(f,c),coast=isCoastal3212(c),road=aiRoadDegree3260(c);
