   tasks:dedup,targets,counts,created:previous?.created??now,updated:now,
   nextEval:now+REGIONAL_PLANNING_SECONDS3284+(f%3)*3,lastWall:wall,
   lastBuiltCell:previousCell,lastBuilt:previous?.lastBuilt??-1e9,
