// Cartographically accurate small Lozoya valley flanks; the basin is less than
// one playable cell across. These separate ridgelines are high-zoom-only strokes.
const LOZOYA_SUBCELL_RIDGES3291=[
 {name:'Montes Carpetanos',width:.91,coordinates:[[-4.08,40.92],[-4.00,40.98],[-3.89,41.015],[-3.77,41.055],[-3.65,41.085],[-3.55,41.11]]},
 {name:'Cuerda Larga y Morcuera',width:.76,coordinates:[[-4.08,40.765],[-3.99,40.788],[-3.93,40.814],[-3.85,40.834],[-3.75,40.858],[-3.68,40.865]]}
];
function drawSubcellRidgelines3291(R,cx,cy){
 if(zoom<6.6)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
 for(const r of LOZOYA_SUBCELL_RIDGES3291){
  let any=false;ctx.beginPath();let pen=false;
  for(let i=0;i<r.coordinates.length-1;i++){
   const a=r.coordinates[i],b=r.coordinates[i+1];
   for(let k=0;k<=5;k++){
    const t=k/5,lng=a[0]+(b[0]-a[0])*t,lat=a[1]+(b[1]-a[1])*t;
    const v=lonLatVec(lng,lat),p=projectVec(v[0],v[1],v[2],R,cx,cy);
    if(p[2]<.035){pen=false;continue}
    if(!pen){ctx.moveTo(p[0],p[1]);pen=true}else ctx.lineTo(p[0],p[1]);any=true;
   }
  }
  if(any){ctx.strokeStyle='rgba(38,31,24,.78)';ctx.lineWidth=r.width*2.5;ctx.stroke();ctx.strokeStyle='rgba(218,181,137,.93)';ctx.lineWidth=r.width;ctx.stroke()}
 }
 ctx.restore();
}

// Variable stroke weights by size, tributaries, branches and strategic zoom.
// Coastal terminal: draw from penultimate junction to the MIDPOINT of the
// coastal shared edge, instead of along its entire coastline (old artifact).
drawTerrain3212=function(R,cx,cy){
 if(zoom<.86)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
 const zf=Math.min(1.15,.74+Math.log2(Math.max(1,zoom))*.085),usedM=new Set(),usedR=new Set();
 for(const sys of MOUNTAIN_NETWORKS3242){
  if(sys.minZoom && zoom<sys.minZoom)continue;
  if(!physicalSystemVisible3242(sys,false))continue;
  const t=sys.tier||1,detail=sys.branch?.73:1,custom=sys.width||1;
  const outer=(t===3?3.2:t===2?2.55:1.75)*zf*custom*detail;
  const inner=(t===3?1.48:t===2?1.08:.7)*zf*custom*detail;
  const ink=t===3?'rgba(206,170,127,.92)':t===2?'rgba(182,146,109,.84)':'rgba(163,127,90,.70)';
  for(const id of sys.edges){if(usedM.has(id))continue;usedM.add(id);drawCanonicalEdge3242(id,R,cx,cy,outer,'rgba(50,40,31,.70)',inner,ink)}
 }
 drawSecondaryRelief3292(R,cx,cy);
 for(const sys of MAP_RIVERS3242){
  if(sys.minZoom&&zoom<sys.minZoom)continue;
  if(!physicalSystemVisible3242(sys,true))continue;
  const nav=NAV_RIVER_NAMES3242.has(sys.n);
  const unit=(sys.width||1)*(sys.branch?.68:1);
  const outer=(nav?2.5:sys.tier>=2?2.05:1.46)*zf*unit;
  const inner=(nav?1.18:sys.tier>=2?.88:.56)*zf*unit;
  const ink=nav?'rgba(92,176,207,.96)':sys.branch?'rgba(101,165,193,.70)':'rgba(93,163,194,.86)';
  const edges=sys.edges,n=edges.length;
  for(let j=0;j<n;j++){
   const id=edges[j];if(usedR.has(id))continue;usedR.add(id);
   const k=j/Math.max(1,n-1),tap=Math.max(.52,Math.min(1.0,.52+k*.6));
   if(sys.mouthExpected&&j===n-1&&PHYS_EDGE_COAST3242[id]){
    const edge=physicalEdge3242(id),prev=n>1?physicalEdge3242(edges[j-1]):null;
    const common=prev?(prev.u===edge.u||prev.v===edge.u?edge.u:edge.v):edge.u;
    const other=common===edge.u?edge.v:edge.u;
    const L=loadLevel(MAX_GAME_LEVEL3233),F=L.faceCenters;
    const a=common*3,b=other*3;
    const p=projectVec(F[a]/32767,F[a+1]/32767,F[a+2]/32767,R,cx,cy);
    const q=projectVec((F[a]+F[b])/65534,(F[a+1]+F[b+1])/65534,(F[a+2]+F[b+2])/65534,R,cx,cy);
    if(p[2]>=.015&&q[2]>=.015){
     ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);
     ctx.strokeStyle='rgba(6,20,29,.42)';ctx.lineWidth=outer*tap;ctx.stroke();
     ctx.strokeStyle=ink;ctx.lineWidth=inner*tap;ctx.stroke();
    }
   }else{drawCanonicalEdge3242(id,R,cx,cy,outer*tap,'rgba(6,20,29,.40)',inner*tap,ink)}
  }
 }
 ctx.restore();
};


// ================= v3.29.2 · MÁS ZOOM + RELIEVE SECUNDARIO GLOBAL =================
drawSubcellRidgelines3291=function(){ /* desactivado: sustituido por relieve global */ };

const RELIEF_SECONDARY_MIN_ZOOM3292=5.15;
const RELIEF_SECONDARY_HI_ZOOM3292=8.0;
let secondaryReliefEdgeSet3292=null;
let secondaryReliefCache3292=null;

function buildSecondaryRelief3292(){
 if(secondaryReliefCache3292)return secondaryReliefCache3292;
 secondaryReliefEdgeSet3292=new Set();
 const riverEdges=new Set();
 for(const sys of MAP_RIVERS3242)for(const id of sys.edges||[])riverEdges.add(id);

 const systems=[];
 for(const sys of MOUNTAIN_NETWORKS3242){
  const tier=sys.tier||1,unit=sys.width||1;
  const secondary=!!(sys.branch||sys.parent||tier<=2||unit<1.02);
  const hiMain=!secondary&&tier>=3&&unit>=1.02;
  if(!secondary&&!hiMain)continue;
  systems.push({sys,secondary,hiMain,tier,unit});
  for(const id of sys.edges||[]){
   if(riverEdges.has(id))continue;
   secondaryReliefEdgeSet3292.add(id);
  }
 }
 secondaryReliefCache3292={systems,riverEdges};
 return secondaryReliefCache3292;
}

function drawSecondaryRelief3292(R,cx,cy){
 if(zoom<RELIEF_SECONDARY_MIN_ZOOM3292)return;
 const cache=buildSecondaryRelief3292();
 const zf=Math.min(1.34,.55+Math.log2(Math.max(1,zoom))*.14);
 const drawn=new Set();
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 for(const item of cache.systems){
  const sys=item.sys,secondary=item.secondary,hiMain=item.hiMain,tier=item.tier,unit=item.unit;
  if(!physicalSystemVisible3242(sys,false))continue;
  if(hiMain && zoom<RELIEF_SECONDARY_HI_ZOOM3292)continue;
  const base=(secondary?(tier>=2?.94:.78):(tier>=3?1.08:.92))*unit*zf;
  const outer=Math.max(.22,Math.min(1.45,base*.34));
  const inner=Math.max(.09,Math.min(.68,base*.14));
  const outerC=secondary?'rgba(55,46,35,.22)':'rgba(61,48,34,.16)';
  const innerC=secondary
    ? (sys.branch?'rgba(160,146,118,.56)':'rgba(140,128,104,.46)')
    : 'rgba(124,113,92,.30)';
  for(const id of sys.edges||[]){
   if(cache.riverEdges.has(id)||drawn.has(id))continue;
   drawn.add(id);
   drawCanonicalEdge3242(id,R,cx,cy,outer,outerC,inner,innerC);
  }
 }

 if(zoom>=9.2){
  const L=loadLevel(MAX_GAME_LEVEL3233),land=L.land;
  for(const id of secondaryReliefEdgeSet3292){
   const e=physicalEdge3242(id),a=e.a,b=e.b;
   if(a<0||b<0||land[a]<0||land[b]<0)continue;
   const ta=mountainTier3212[a]||0,tb=mountainTier3212[b]||0;
   if(ta===tb||(!ta&&!tb))continue;
   if(Math.abs(ta-tb)<1)continue;
   drawCanonicalEdge3242(id,R,cx,cy,.18,'rgba(48,44,38,.10)',.08,'rgba(188,180,164,.12)');
  }
 }
 ctx.restore();
}

