// Objetivo:
// - mejorar la lectura de las cordilleras (jerarquía visual y ramales);
// - mejorar visualmente las desembocaduras, evitando colas costeras raras;
// - hacer los ríos principales más legibles sin saturar el mapa.
//
// Esta versión NO inventa geometría libre. Todo sigue dibujándose sobre
// nodos y aristas reales de la malla.

const MAJOR_RIVER_NAMES3293=new Set([
 'Amazonas','Nilo','Yangtsé','Misisipi-Misuri','Danubio','Misisipi','Yangtsé-Kiang',
 'Mississippi-Missouri','Mississippi','Volga','Mekong','Ganges','Indo','Lena',
 'Obi','Yeniséi','Paraná','Orinoco','Congo','Rin','Ródano','Po','Ebro','Tajo',
 'Duero','Guadalquivir'
]);

const MAJOR_MOUNTAIN_NAMES3293=new Set([
 'Andes','Rocosas','Alpes','Himalaya','Cáucaso','Pirineos','Atlas',
 'Apeninos','Cárpatos','Montes Escandinavos','Urales','Sistema Central',
 'Cordillera Cantábrica','Sistema Ibérico','Cordilleras Béticas'
]);

let riverRenderCache3293=new Map();

function clearGeoFineCache3293(){ riverRenderCache3293=new Map(); }

function nodeVec3293(nodeId){
 const L=loadLevel(MAX_GAME_LEVEL3233),F=L.faceCenters,i=nodeId*3;
 return [F[i]/32767,F[i+1]/32767,F[i+2]/32767];
}
function edgeMidVec3293(edgeId){
 const e=physicalEdge3242(edgeId),a=nodeVec3293(e.u),b=nodeVec3293(e.v);
 return slerp3212(a,b,.5);
}

function buildRiverRenderPlan3293(sys){
 if(riverRenderCache3293.has(sys.n))return riverRenderCache3293.get(sys.n);
 const plan={edges:sys.edges.slice(),tail:[],mouthEdge:sys.mouth,startNode:-1,targetVec:null,ok:false};
 if(sys.branch||!sys.mouthExpected||sys.mouth<0){
   plan.ok=false;
   riverRenderCache3293.set(sys.n,plan);
   return plan;
 }

 // Remove any coastal "tail" at the end; we will replace it with one clean mouth.
 while(plan.edges.length>1){
   const last=physicalEdge3242(plan.edges[plan.edges.length-1]);
   if(!last.coast)break;
   plan.tail.unshift(plan.edges.pop());
 }
 if(!plan.tail.length){
   // Standard case: hide the last mouth edge and replace it with a short, clean exit.
   if(plan.edges.length>1 && plan.edges[plan.edges.length-1]===sys.mouth){
     plan.tail=[plan.edges.pop()];
   }else{
     plan.tail=[sys.mouth];
   }
 }
 const targetEdge=plan.tail[0];
 const nodes=edgePathNodes3242({n:sys.n+'#r3293',branch:sys.branch,parent:sys.parent,edges:[...plan.edges,targetEdge]});
 const tailLen=plan.tail.length;
 const startIndex=Math.max(0,nodes.length-tailLen-1);
 plan.startNode=nodes[startIndex] ?? nodes[Math.max(0,nodes.length-2)] ?? -1;
 plan.mouthEdge=targetEdge;
 plan.targetVec=edgeMidVec3293(targetEdge);
 plan.ok=plan.startNode>=0 && !!plan.targetVec;
 riverRenderCache3293.set(sys.n,plan);
 return plan;
}

function drawRiverMouth3293(sys,R,cx,cy,outerW,outerC,innerW,innerC){
 const plan=buildRiverRenderPlan3293(sys);
 if(!plan.ok)return false;
 const a3=nodeVec3293(plan.startNode), b3=plan.targetVec;
 const a=projectVec(a3[0],a3[1],a3[2],R,cx,cy),
       b=projectVec(b3[0],b3[1],b3[2],R,cx,cy);
 if(a[2]<.015||b[2]<.015)return false;
 ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
 ctx.strokeStyle=outerC;ctx.lineWidth=outerW*1.04;ctx.stroke();
 ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
 ctx.strokeStyle=innerC;ctx.lineWidth=innerW*1.1;ctx.stroke();

 // Very discreet terminal widening on big rivers only.
 const big=(sys.tier||1)>=3||MAJOR_RIVER_NAMES3293.has(sys.n)||sys.nav;
 if(big && zoom>2.4){
   ctx.beginPath();ctx.arc(b[0],b[1],Math.max(.65,innerW*.55),0,Math.PI*2);
   ctx.fillStyle=innerC;ctx.fill();
 }
 return true;
}

function mountainStroke3293(sys,zf){
 const t=sys.tier||1, branch=!!sys.branch, major=MAJOR_MOUNTAIN_NAMES3293.has(sys.n);
 const longness=Math.min(1.22, .92 + (sys.edges?.length||0)/240);
 let ow=(t===3?3.18:t===2?2.48:1.82)*zf*longness;
 let iw=(t===3?1.34:t===2?1.00:.68)*zf*longness;
 if(branch){ow*=.82;iw*=.78}
 if(major && !branch){ow*=1.08;iw*=1.05}
 const outer=t===3?'rgba(74,52,34,.84)':t===2?'rgba(68,49,34,.72)':'rgba(63,46,35,.58)';
 const inner=t===3?'rgba(204,165,120,.90)':t===2?'rgba(186,148,108,.82)':'rgba(157,124,92,.66)';
 return {ow,iw,outer,inner};
}

function riverStroke3293(sys,zf){
 const t=sys.tier||1, branch=!!sys.branch, nav=!!sys.nav, major=MAJOR_RIVER_NAMES3293.has(sys.n);
 let ow=(t===3?2.55:t===2?1.96:1.34)*zf;
 let iw=(t===3?1.42:t===2?1.03:.66)*zf;
 if(branch){ow*=.78;iw*=.76}
 if(nav||major){ow*=1.10;iw*=1.08}
 const outer='rgba(3,16,27,.52)';
 const inner=t===3?'rgba(108,205,218,.98)':t===2?'rgba(89,191,207,.94)':'rgba(75,178,195,.88)';
 return {ow,iw,outer,inner};
}

// Full renderer override
drawTerrain3212=function(R,cx,cy){
 if(zoom<.84)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.24,.90+Math.log2(Math.max(1,zoom))*.082);

 // Main mountain systems
 for(const sys of MOUNTAIN_NETWORKS3242){
   if(!physicalSystemVisible3242(sys,false))continue;
   const s=mountainStroke3293(sys,zf);
   for(const id of sys.edges){
     if(drawnM.has(id))continue;drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }

 // Secondary relief / valleys globally
 drawSecondaryRelief3292(R,cx,cy);

 // Rivers
 for(const sys of MAP_RIVERS3242){
   if(!physicalSystemVisible3242(sys,true))continue;
   const s=riverStroke3293(sys,zf);
   const plan=!sys.branch && sys.mouthExpected ? buildRiverRenderPlan3293(sys) : null;
   const skipTail=plan && plan.tail ? new Set(plan.tail) : null;

   for(const id of sys.edges){
     if(skipTail && skipTail.has(id))continue;
     if(drawnR.has(id))continue;drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }

   if(plan && plan.ok){
     drawRiverMouth3293(sys,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }else if(!sys.branch && sys.mouthExpected && sys.mouth>=0 && !drawnR.has(sys.mouth)){
     drawnR.add(sys.mouth);
     drawCanonicalEdge3242(sys.mouth,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }

 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

const _resetGeoFine3293=resetGame3230;
resetGame3230=function(clearSave=true){
 clearGeoFineCache3293();
 return _resetGeoFine3293(clearSave);
};

const _debugGeoFine3293=debug3230;
debug3230=function(){
 _debugGeoFine3293();
 const el=document.getElementById('debugText3230');
 if(!el||!showDebug3230)return;
 let tails=0;
 for(const r of MAP_RIVERS3242){
   if(r.branch||!r.mouthExpected)continue;
   const p=buildRiverRenderPlan3293(r);
   if(p.tail?.length)tails++;
 }
 el.textContent+=`\\nGeo fina v3.29.3 · desembocaduras limpias ${tails} · cordilleras jerarquizadas`;
};
// ================= /v3.29.3 =================


// ================= v3.29.4 · COSTAS, RÍOS Y CORDILLERAS GLOBAL =================
//
// Ajustes:
// - desembocaduras terminan exactamente en la intersección costa/tierra-mar,
//   no dentro del hexágono marino ni siguiendo la costa;
// - se elimina la etiqueta "valle del Lozoya";
// - se refuerza la lectura de algunas cordilleras/ríos clave sin romper la
//   jerarquía mundial.
//
// Filosofía: mejorar globalmente la geografía visual del juego sin apartarse
// de la topología real de la malla.

const FOCUS_RIVERS3294=new Set([
 'Ebro','Tajo','Guadiana','Guadalquivir','Duero','Rin','Ródano','Po','Danubio',
 'Nilo','Amazonas','Misisipi-Misuri','Yangtsé','Ganges','Mekong','Indo'
]);
const FOCUS_MOUNTAINS3294=new Set([
 'Pirineos','Sistema Central','Sistema Ibérico','Cordillera Cantábrica',
 'Cordilleras Béticas','Alpes','Andes','Rocosas','Himalaya','Atlas','Apeninos'
]);

let riverRenderCache3294=new Map();
function clearGeoFineCache3294(){ riverRenderCache3294=new Map(); }

function buildRiverRenderPlan3294(sys){
 if(riverRenderCache3294.has(sys.n))return riverRenderCache3294.get(sys.n);
 const plan={edges:sys.edges.slice(),tail:[],mouthEdge:sys.mouth,startNode:-1,coastNode:-1,endVec:null,ok:false};
 if(sys.branch||!sys.mouthExpected||sys.mouth<0){
   riverRenderCache3294.set(sys.n,plan); return plan;
 }

 // Retirar todos los segmentos costeros finales para que la desembocadura no "patine" por la costa.
 while(plan.edges.length>1){
   const last=physicalEdge3242(plan.edges[plan.edges.length-1]);
   if(!last.coast)break;
   plan.tail.unshift(plan.edges.pop());
 }
 // Si no hay cola costera, al menos sustituimos el último borde de boca por un final limpio.
 if(!plan.tail.length){
   if(plan.edges.length>1 && plan.edges[plan.edges.length-1]===sys.mouth) plan.tail=[plan.edges.pop()];
   else plan.tail=[sys.mouth];
 }

 const targetEdge=plan.tail[0];
 const allEdges=[...plan.edges,targetEdge];
 const nodes=edgePathNodes3242({n:sys.n+'#r3294',branch:sys.branch,parent:sys.parent,edges:allEdges});
 const tailLen=plan.tail.length;
 const startIndex=Math.max(0,nodes.length-tailLen-1);
 plan.startNode=nodes[startIndex] ?? -1;
 // Punto exacto de costa donde el río debe terminar.
 plan.coastNode=nodes[startIndex+1] ?? -1;
 if(plan.startNode>=0 && plan.coastNode>=0){
   plan.endVec=nodeVec3293(plan.coastNode);
   plan.ok=true;
 }
 riverRenderCache3294.set(sys.n,plan);
 return plan;
}

function drawRiverMouth3294(sys,R,cx,cy,outerW,outerC,innerW,innerC){
 const plan=buildRiverRenderPlan3294(sys);
 if(!plan.ok)return false;
 const a3=nodeVec3293(plan.startNode), b3=plan.endVec;
 const a=projectVec(a3[0],a3[1],a3[2],R,cx,cy),
       b=projectVec(b3[0],b3[1],b3[2],R,cx,cy);
 if(a[2]<.015||b[2]<.015)return false;
 ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
 ctx.strokeStyle=outerC;ctx.lineWidth=outerW*1.04;ctx.stroke();
 ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);
 ctx.strokeStyle=innerC;ctx.lineWidth=innerW*1.08;ctx.stroke();
 return true;
}

function mountainStroke3294(sys,zf){
 const t=sys.tier||1, branch=!!sys.branch;
 const major=MAJOR_MOUNTAIN_NAMES3293.has(sys.n)||FOCUS_MOUNTAINS3294.has(sys.n);
 const longness=Math.min(1.24, .94 + (sys.edges?.length||0)/230);
 let ow=(t===3?3.24:t===2?2.54:1.86)*zf*longness;
 let iw=(t===3?1.38:t===2?1.03:.70)*zf*longness;
 if(branch){ow*=.80;iw*=.77}
 if(major && !branch){ow*=1.12;iw*=1.08}
 const outer=t===3?'rgba(74,52,34,.86)':t===2?'rgba(69,49,34,.74)':'rgba(63,46,35,.60)';
 const inner=t===3?'rgba(206,167,121,.92)':t===2?'rgba(188,150,108,.84)':'rgba(160,126,93,.68)';
 return {ow,iw,outer,inner};
}
function riverStroke3294(sys,zf){
 const t=sys.tier||1, branch=!!sys.branch, nav=!!sys.nav;
 const major=MAJOR_RIVER_NAMES3293.has(sys.n)||FOCUS_RIVERS3294.has(sys.n);
 let ow=(t===3?2.62:t===2?2.00:1.36)*zf;
 let iw=(t===3?1.46:t===2?1.05:.67)*zf;
 if(branch){ow*=.77;iw*=.75}
 if(nav||major){ow*=1.10;iw*=1.09}
 const outer='rgba(3,16,27,.54)';
 const inner=t===3?'rgba(113,208,221,.98)':t===2?'rgba(92,194,210,.95)':'rgba(78,180,197,.88)';
 return {ow,iw,outer,inner};
}

// Eliminar etiqueta problemática del valle del Lozoya.
for(let i=GEOGRAPHIC_LOCAL_REGIONS.length-1;i>=0;i--){
 const l=GEOGRAPHIC_LOCAL_REGIONS[i];
 const nm=(l.name||'').toLowerCase();
 if(l.id==='geo_lozoya3291' || nm==='valle del lozoya') GEOGRAPHIC_LOCAL_REGIONS.splice(i,1);
}

// Override del renderer físico final.
drawTerrain3212=function(R,cx,cy){
 if(zoom<.84)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.26,.91+Math.log2(Math.max(1,zoom))*.083);

 for(const sys of MOUNTAIN_NETWORKS3242){
   if(!physicalSystemVisible3242(sys,false))continue;
   const s=mountainStroke3294(sys,zf);
   for(const id of sys.edges){
     if(drawnM.has(id))continue; drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }
 drawSecondaryRelief3292(R,cx,cy);

 for(const sys of MAP_RIVERS3242){
   if(!physicalSystemVisible3242(sys,true))continue;
   const s=riverStroke3294(sys,zf);
   const plan=!sys.branch&&sys.mouthExpected ? buildRiverRenderPlan3294(sys) : null;
   const skipTail=plan&&plan.tail ? new Set(plan.tail) : null;

   for(const id of sys.edges){
     if(skipTail && skipTail.has(id))continue;
     if(drawnR.has(id))continue; drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
   if(plan&&plan.ok){
     drawRiverMouth3294(sys,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }else if(!sys.branch&&sys.mouthExpected&&sys.mouth>=0 && !drawnR.has(sys.mouth)){
     drawnR.add(sys.mouth);
     drawCanonicalEdge3242(sys.mouth,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }
 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

