// ================= v3.29.5 · DESEMBOCADURAS CORREGIDAS =================
//
// Cambio de enfoque:
// En lugar de "reconstruir" la boca del río con el mouth declarado,
// recortamos el río en su PRIMER contacto real con el mar.
// Así evitamos por completo que el cauce siga dibujándose por la costa
// o bordeando hexágonos marítimos.
//

let riverRenderCache3295 = new Map();

function clearGeoFineCache3295(){ riverRenderCache3295 = new Map(); }

function edgeTouchesSea3295(edgeId){
  const e = physicalEdge3242(edgeId);
  if(e.coast) return true;
  const L = loadLevel(MAX_GAME_LEVEL3233), land = L.land;
  const aLand = e.a>=0 ? land[e.a] >= 0 : false;
  const bLand = e.b>=0 ? land[e.b] >= 0 : false;
  // costa real = un lado tierra y el otro mar / exterior
  return aLand !== bLand;
}

function buildRiverRenderPlan3295(sys){
  if(riverRenderCache3295.has(sys.n)) return riverRenderCache3295.get(sys.n);
  const plan = {visibleEdges: sys.edges.slice(), cutIndex:-1, ok:true};
  if(!sys.branch && sys.mouthExpected){
    let firstSea = -1;
    for(let i=0;i<sys.edges.length;i++){
      if(edgeTouchesSea3295(sys.edges[i])){ firstSea = i; break; }
    }
    if(firstSea >= 0){
      plan.cutIndex = firstSea;
      plan.visibleEdges = sys.edges.slice(0, firstSea + 1);
    }
  }
  riverRenderCache3295.set(sys.n, plan);
  return plan;
}

drawTerrain3212=function(R,cx,cy){
 if(zoom<.84)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.26,.91+Math.log2(Math.max(1,zoom))*.083);

 for(const sys of MOUNTAIN_NETWORKS3242){
   if(!physicalSystemVisible3242(sys,false))continue;
   const s=mountainStroke3294(sys,zf);
   for(const id of sys.edges){
     if(drawnM.has(id))continue; drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }
 drawSecondaryRelief3292(R,cx,cy);

 for(const sys of MAP_RIVERS3242){
   if(!physicalSystemVisible3242(sys,true))continue;
   const s=riverStroke3294(sys,zf);
   const plan = buildRiverRenderPlan3295(sys);
   for(const id of plan.visibleEdges){
     if(drawnR.has(id))continue; drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }
 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

