// ================= v3.29.6 · DESEMBOCADURAS FINAS =================
//
// v3.29.5 mejoró el problema general, pero todavía dibujaba algunos ríos
// sobre la arista costera final. En esta versión el río ya NO dibuja esa
// arista mar-costa: termina exactamente en el vértice costero donde el
// cauce interior toca por primera vez el mar.

let riverRenderCache3296 = new Map();

function clearGeoFineCache3296(){ riverRenderCache3296 = new Map(); }

function buildRiverRenderPlan3296(sys){
  if(riverRenderCache3296.has(sys.n)) return riverRenderCache3296.get(sys.n);
  const plan = {
    visibleEdges: sys.edges.slice(),
    firstSea:-1,
    endFromNode:-1,
    endToNode:-1,
    ok:true
  };
  if(!sys.branch && sys.mouthExpected){
    let firstSea = -1;
    for(let i=0;i<sys.edges.length;i++){
      if(edgeTouchesSea3295(sys.edges[i])){ firstSea = i; break; }
    }
    if(firstSea >= 0){
      plan.firstSea = firstSea;
      const prefix = sys.edges.slice(0, firstSea+1);
      const nodes = edgePathNodes3242({n:sys.n+'#r3296',branch:false,parent:sys.parent,edges:prefix});
      // nodes length should be edges+1. The river should stop at node[firstSea],
      // i.e. the coastal intersection BEFORE traversing the sea-touching edge.
      const coastNode = nodes[firstSea];
      const fromNode  = nodes[Math.max(0, firstSea-1)];
      if(firstSea===0){
        // Path touches coast immediately. Keep no regular edges and just skip custom mouth.
        plan.visibleEdges = [];
        plan.endFromNode = -1;
        plan.endToNode = coastNode ?? -1;
      }else{
        plan.visibleEdges = sys.edges.slice(0, firstSea); // EXCLUDE the coastal edge itself
        plan.endFromNode = fromNode ?? -1;
        plan.endToNode   = coastNode ?? -1;
      }
      plan.ok = true;
    }
  }
  riverRenderCache3296.set(sys.n, plan);
  return plan;
}

function drawRiverMouth3296(sys,R,cx,cy,outerW,outerC,innerW,innerC){
  const plan = buildRiverRenderPlan3296(sys);
  if(plan.endFromNode < 0 || plan.endToNode < 0) return false;
  const a3 = nodeVec3293(plan.endFromNode), b3 = nodeVec3293(plan.endToNode);
  const a = projectVec(a3[0],a3[1],a3[2],R,cx,cy),
        b = projectVec(b3[0],b3[1],b3[2],R,cx,cy);
  if(a[2]<.015 || b[2]<.015) return false;
  ctx.beginPath(); ctx.moveTo(a[0],a[1]); ctx.lineTo(b[0],b[1]);
  ctx.strokeStyle = outerC; ctx.lineWidth = outerW*1.03; ctx.stroke();
  ctx.beginPath(); ctx.moveTo(a[0],a[1]); ctx.lineTo(b[0],b[1]);
  ctx.strokeStyle = innerC; ctx.lineWidth = innerW*1.06; ctx.stroke();
  return true;
}

