// ================= /v3.29.6 =================


// ================= v3.29.7 · REEQUILIBRIO GEOGRÁFICO MUNDIAL =================
//
// Objetivo:
// - limpiar un poco Iberia sin perder sus grandes cuencas;
// - hacer que el resto del mundo se vea menos "pobre";
// - mantener jerarquía: grandes sistemas visibles pronto, secundarios al acercarse;
// - conservar las desembocaduras exactas de v3.29.6.
//
// No se eliminan datos geográficos del juego: se reequilibra su visibilidad,
// grosor y momento de aparición.

const IBERIA_RIVERS_MAJOR3297 = new Set([
 'Miño','Duero','Tajo','Guadiana','Guadalquivir','Ebro'
]);
const IBERIA_RIVERS_MEDIUM3297 = new Set([
 'Júcar','Segura'
]);
const IBERIA_RIVERS_MINOR3297 = new Set([
 'Bidasoa','Nalón','Llobregat','Ter','Lozoya'
]);

const WORLD_MAJOR_TRIBUTARIES3297 = new Set([
 'Misuri','Ohio','Madeira','Negro','Marañón','Nilo Azul','Nilo Blanco',
 'Tisza','Paraguay','Benue','Brahmaputra','Irtish'
]);

const WORLD_SECONDARY_MOUNTAINS3297 = new Set([
 'Jura','Pindo','Cordillera de Alaska','Montañas Costeras','Cascadas',
 'Sierra Madre Occidental','Sierra Madre Oriental','Eje Volcánico Transmexicano',
 'Andes septentrionales','Cordillera Oriental Andina','Virunga','Pamir',
 'Karakórum','Sayan','Hengduan','Alpes Australianos'
]);

function riverMinZoom3297(sys){
  // Iberia: menos ruido a zoom medio.
  if(IBERIA_RIVERS_MAJOR3297.has(sys.n)) return Math.max(.92, sys.minZoom||0);
  if(IBERIA_RIVERS_MEDIUM3297.has(sys.n)) return Math.max(2.75, sys.minZoom||0);
  if(IBERIA_RIVERS_MINOR3297.has(sys.n)){
    if(sys.n==='Lozoya') return 8.5;
    return Math.max(4.4, sys.minZoom||0);
  }

  // Resto del mundo: los afluentes importantes aparecen antes para dar riqueza.
  if(sys.branch){
    if(WORLD_MAJOR_TRIBUTARIES3297.has(sys.n)) return 1.55;
    return 1.95;
  }
  if((sys.tier||1)>=3 || sys.nav) return .86;
  if((sys.tier||1)===2) return 1.08;
  return 1.62;
}

function mountainMinZoom3297(sys){
  if(sys.minZoom) return sys.minZoom;
  if(sys.branch || WORLD_SECONDARY_MOUNTAINS3297.has(sys.n)){
    if((sys.tier||1)>=3) return 1.18;
    if((sys.tier||1)===2) return 1.48;
    return 1.95;
  }
  if((sys.tier||1)>=3) return .84;
  if((sys.tier||1)===2) return 1.06;
  return 1.55;
}

function riverStroke3297(sys,zf){
  const base = riverStroke3294(sys,zf);
  let factor=1;

  if(IBERIA_RIVERS_MAJOR3297.has(sys.n)) factor=.96;
  else if(IBERIA_RIVERS_MEDIUM3297.has(sys.n)) factor=.78;
  else if(IBERIA_RIVERS_MINOR3297.has(sys.n)) factor=.56;
  else if(sys.branch){
    factor=WORLD_MAJOR_TRIBUTARIES3297.has(sys.n)?.82:.64;
  }else if((sys.tier||1)===1){
    factor=.76;
  }

  return {
    ow:Math.max(.40,base.ow*factor),
    iw:Math.max(.18,base.iw*factor),
    outer:base.outer,
    inner:base.inner
  };
}

function mountainStroke3297(sys,zf){
  const base=mountainStroke3294(sys,zf);
  let factor=1;

  if(sys.branch){
    // Ramales globales visibles pero discretos.
    factor=(sys.tier||1)>=3?.88:(sys.tier||1)===2?.78:.68;
  }else if((sys.tier||1)===1){
    factor=.82;
  }

  // Los grandes sistemas mantienen presencia.
  if(FOCUS_MOUNTAINS3294.has(sys.n) || MAJOR_MOUNTAIN_NAMES3293.has(sys.n))
    factor=Math.max(factor,1.02);

  return {
    ow:Math.max(.55,base.ow*factor),
    iw:Math.max(.22,base.iw*factor),
    outer:base.outer,
    inner:base.inner
  };
}

// Renderer geográfico final v3.29.7.
drawTerrain3212=function(R,cx,cy){
 if(zoom<.82)return;
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';

 const drawnM=new Set(),drawnR=new Set();
 const zf=Math.min(1.26,.91+Math.log2(Math.max(1,zoom))*.083);

 // Cordilleras: más riqueza mundial en ramales/secundarias.
 for(const sys of MOUNTAIN_NETWORKS3242){
   if(zoom<mountainMinZoom3297(sys))continue;
   const s=mountainStroke3297(sys,zf);
   for(const id of sys.edges){
     if(drawnM.has(id))continue; drawnM.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }
 }

 // Relieve secundario solo a partir de zoom suficiente, como en 3292.
 drawSecondaryRelief3292(R,cx,cy);

 // Hidrografía con densidad equilibrada.
 for(const sys of MAP_RIVERS3242){
   if(zoom<riverMinZoom3297(sys))continue;
   const s=riverStroke3297(sys,zf);
   const plan=buildRiverRenderPlan3296(sys);

   for(const id of plan.visibleEdges){
     if(drawnR.has(id))continue; drawnR.add(id);
     drawCanonicalEdge3242(id,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
   }

   // Desembocadura exacta en vértice costa/tierra-mar.
   if(!sys.branch && sys.mouthExpected)
     drawRiverMouth3296(sys,R,cx,cy,s.ow,s.outer,s.iw,s.inner);
 }

 drawRhineUpper3252(R,cx,cy,zf);
 ctx.restore();
};

