let stabilityLast3298=null;

function validateStability3298(showToast=true){
 const t0=performance.now(),errors=[],warnings=[],L=loadLevel(MAX_GAME_LEVEL3233),n=L.n;

 if(!owner6||owner6.length!==n)errors.push(`owner6 ${owner6?.length||0}/${n}`);
 if(!forts3212||forts3212.length!==n)errors.push(`forts ${forts3212?.length||0}/${n}`);
 if(typeof cityLevel3230!=='undefined'&&cityLevel3230.length!==n)errors.push(`cityLevel ${cityLevel3230.length}/${n}`);
 if(typeof industryLevel3230!=='undefined'&&industryLevel3230.length!==n)errors.push(`industryLevel ${industryLevel3230.length}/${n}`);

 // IDs y valores de propietario.
 let invalidOwner=0;
 for(let i=0;i<n;i++){
   const o=owner6[i];
   if(o < -1 || o >= FACTIONS3230.length){invalidOwner++;if(invalidOwner>20)break}
 }
 if(invalidOwner)errors.push(`${invalidOwner}${invalidOwner>20?'+':''} propietarios inválidos`);

 // Carreteras.
 let badRoads=0,badRoadCells=0;
 for(const path of roads3212){
   if(!Array.isArray(path)||path.length<2){badRoads++;continue}
   for(const c of path)if(c<0||c>=n){badRoadCells++;break}
 }
 if(badRoads||badRoadCells)errors.push(`carreteras inválidas ${badRoads}/${badRoadCells}`);

 // Transportes.
 let badFleets=0;
 for(const f of fleets3212){
   if((f.from??-1)<0||(f.from??-1)>=n||(f.to??-1)<0||(f.to??-1)>=n)badFleets++;
   if((f.troops??0)<0)badFleets++;
 }
 if(badFleets)errors.push(`transportes inválidos ${badFleets}`);

 // Frentes del jugador.
 let badPlayerFronts=0;
 for(const f of activeFronts3230){
   if((f.pool??0)<0||(f.goal??-1)<0||(f.goal??-1)>=n)badPlayerFronts++;
 }
 if(badPlayerFronts)errors.push(`frentes jugador inválidos ${badPlayerFronts}`);

 // Campañas IA: tropas nunca negativas, objetivo real y fases válidas.
 let badAIFronts=0,duplicateIds=0;
 const ids=new Set();
 for(const f of aiFronts3280){
   if(ids.has(f.id))duplicateIds++;else ids.add(f.id);
   if(f.nationId<=0||f.nationId>=FACTIONS3230.length)badAIFronts++;
   if((f.assignedForces??0)<0||(f.reserveForces??0)<0)badAIFronts++;
   if(f.objective<0||f.objective>=n)badAIFronts++;
   if(!AI_FRONT_PHASES3280.includes(f.phase))badAIFronts++;
 }
 if(duplicateIds)errors.push(`IDs de frente IA duplicados ${duplicateIds}`);
 if(badAIFronts)errors.push(`frentes IA inválidos ${badAIFronts}`);

 // Reservas y guarniciones IA.
 let negativeArmy=0;
 for(let f=0;f<FACTIONS3230.length;f++){
   if((troops3230[f]??0)<-.001)negativeArmy++;
   const m=aiMilitary3280?.[f];
   if(m&&(m.capitalDefense<0||m.territorialDefense<0||m.coastalDefense<0||m.reserveTarget<0))negativeArmy++;
 }
 if(negativeArmy)errors.push(`reservas/guarniciones negativas ${negativeArmy}`);

 // Geografía.
 const geo=validatePhysicalGeography3242(false);
 if(geo.errors)errors.push(`geografía física ${geo.errors} incidencias`);

 // Desembocaduras v3.29.6.
 let mouths=0,badMouths=0;
 for(const r of MAP_RIVERS3242){
   if(r.branch||!r.mouthExpected)continue;
   const p=buildRiverRenderPlan3296(r);
   mouths++;
   if(p.firstSea<0||p.endToNode<0)badMouths++;
 }
 if(badMouths)warnings.push(`${badMouths}/${mouths} desembocaduras sin corte exacto`);

 if(renderMsAvg3255>36)warnings.push(`render medio alto ${renderMsAvg3255.toFixed(1)} ms`);
 if(stabilityPerf3298.aiAvg>45)warnings.push(`IA pesada ${stabilityPerf3298.aiAvg.toFixed(1)} ms`);
 if(stabilityPerf3298.frontsAvg>30)warnings.push(`frentes pesados ${stabilityPerf3298.frontsAvg.toFixed(1)} ms`);
 if(aiFrontPathCache3280?.size>AI_FRONT_PATH_CACHE_MAX3280)warnings.push(`cache rutas IA ${aiFrontPathCache3280.size}`);

 const mem=(performance.memory&&performance.memory.usedJSHeapSize)
   ? Math.round(performance.memory.usedJSHeapSize/1048576)
   : null;

 stabilityLast3298={
   ok:errors.length===0,errors,warnings,
   ms:performance.now()-t0,
   cells:n,
   renderAvg:renderMsAvg3255,
   renderMax:renderMsMax3255,
   aiAvg:stabilityPerf3298.aiAvg,
   frontsAvg:stabilityPerf3298.frontsAvg,
   economyAvg:stabilityPerf3298.economyAvg,
   ownerCacheMs:ownerCacheBuildMs3298,
   rankingMs:rankingCountMs3298,
   heapMB:mem,
   mouths,badMouths
 };

 if(showToast){
   if(errors.length)toast(`Estabilidad: ${errors.length} error(es)`);
   else if(warnings.length)toast(`Estabilidad OK · ${warnings.length} aviso(s)`);
   else toast('Estabilidad: OK');
   debug3230();
 }
 return stabilityLast3298;
}

