// Capture a simple tap/click while preserving the ORIGINAL drag/zoom gestures.
// IMPORTANT: when this handler consumes a setup tap it must also do the cleanup
// normally performed by the historical pointerup listener. Otherwise a stale
// pointer remains in `pointers` and the first real turn is interpreted as a
// multi-touch gesture.
canvas.addEventListener('pointerup',e=>{
 if(!newGamePlacementMode3302||dragMoved)return;
 if(pointers.size!==1||!pointers.has(e.pointerId))return;
 const cell=mapHitCell3244(e.clientX,e.clientY);
 if(cell<0)return;

 // Equivalent cleanup to the original map pointerup before consuming the event.
 pointers.delete(e.pointerId);
 try{
   if(canvas.hasPointerCapture?.(e.pointerId))canvas.releasePointerCapture(e.pointerId);
 }catch(_){}
 dragMoved=false;

 e.preventDefault();e.stopImmediatePropagation();
 selectNewGameCell3302(cell);
},true);

